157	fn canonical_artifact_root(artifact_root: &Path) -> Result<PathBuf, GraphError> {
158	    let metadata = fs::metadata(artifact_root).map_err(|error| GraphError::ArtifactRead {
159	        path: artifact_root.to_path_buf(),
160	        message: error.to_string(),
161	    })?;
162	    if !metadata.is_dir() {
163	        return Err(GraphError::UnsafeArtifactPath {
164	            path: artifact_root.to_path_buf(),
165	            reason: "artifact root is not a directory",
166	        });
167	    }
168	    artifact_root.canonicalize().map_err(|error| GraphError::ArtifactRead {
169	        path: artifact_root.to_path_buf(),
170	        message: error.to_string(),
171	    })
172	}
173	
174	fn resolve_asset_path(root: &Path, asset_name: &str) -> Result<PathBuf, GraphError> {
175	    let relative = Path::new(asset_name);
176	    if relative.components().count() != 1 || !matches!(relative.components().next(), Some(Component::Normal(_))) {
177	        return Err(GraphError::UnsafeArtifactPath {
178	            path: relative.to_path_buf(),
179	            reason: "asset name is not a single relative file name",
180	        });
181	    }
182	    let candidate = root.join(relative);
183	    let metadata = fs::symlink_metadata(&candidate).map_err(|error| GraphError::ArtifactRead {
184	        path: candidate.clone(),
185	        message: error.to_string(),
186	    })?;
187	    if metadata.file_type().is_symlink() {
188	        return Err(GraphError::UnsafeArtifactPath {
189	            path: candidate,
190	            reason: "symbolic links are not accepted as artifacts",
191	        });
192	    }
193	    if !metadata.is_file() {
194	        return Err(GraphError::UnsafeArtifactPath {
195	            path: candidate,
196	            reason: "artifact is not a regular file",
197	        });
198	    }
199	    let canonical = candidate.canonicalize().map_err(|error| GraphError::ArtifactRead {
200	        path: candidate.clone(),
201	        message: error.to_string(),
202	    })?;
203	    if !canonical.starts_with(root) {
204	        return Err(GraphError::UnsafeArtifactPath {
205	            path: canonical,
206	            reason: "artifact resolves outside artifact root",
207	        });
208	    }
209	    Ok(canonical)
210	}
