212	fn verify_github_attestation<R: CommandRunner>(
213	    path: &Path,
214	    entry: &callisto_model::ArtifactManifestEntryV1,
215	    runner: &R,
216	) -> Result<(), GraphError> {
217	    let attestation_policy = &entry.slot.attestation_policy;
218	    let repository_slug = attestation_policy.repository.as_slug();
219	    let workflow = format!("{repository_slug}/{}", attestation_policy.workflow_path);
220	    let path_argument = path.to_string_lossy();
221	    let source_commit = entry.attestation.source_commit.as_str();
222	    let args = [
223	        "attestation",
224	        "verify",
225	        path_argument.as_ref(),
226	        "--repo",
227	        repository_slug.as_str(),
228	        "--signer-workflow",
229	        workflow.as_str(),
230	        "--signer-digest",
231	        attestation_policy.workflow_commit.as_str(),
232	        "--source-digest",
233	        source_commit,
234	        "--deny-self-hosted-runners",
235	    ];
236	    let cwd = path.parent().unwrap_or_else(|| Path::new("."));
237	    let sleeper = policy::ThreadSleeper;
238	    let succeeded = retry_observation(&sleeper, || attempt_attestation_verify(runner, &args, cwd))?;
239	    if succeeded {
240	        Ok(())
241	    } else {
242	        Err(GraphError::ArtifactAttestation {
243	            path: path.to_path_buf(),
244	            message: "GitHub attestation verification failed".to_owned(),
245	        })
246	    }
247	}
