 36	    fn observe(
 37	        &self,
 38	        context: &ProviderContext<'_>,
 39	        request: &ProviderRequest<'_>,
 40	    ) -> Result<ProviderObservationV1, GraphError> {
 41	        let operation = registry_operation(request)?;
