113	pub fn is_safe_artifact_component(value: &str) -> bool {
114	    !value.is_empty()
115	        && value.len() <= 255
116	        && !value.contains("..")
117	        // `.` names the directory being joined, not a file in it.
118	        && value != "."
119	        && value
120	            .bytes()
121	            .all(|byte| byte.is_ascii_alphanumeric() || matches!(byte, b'.' | b'_' | b'-'))
