355	/// Resolves the interpreter for the PyPI build step's `python -m build`:
356	/// prefers `python3` -- the only name macOS and Debian systems guarantee --
357	/// and falls back to bare `python` for systems that only ship that. Errors
358	/// naming both when neither is on `path_value`.
359	///
360	/// `path_value` is injected rather than read from `$PATH` directly so tests
361	/// can exercise both resolutions and the error without mutating process-wide
362	/// environment state.
363	fn resolve_python_interpreter(path_value: Option<&OsStr>) -> Result<&'static str, GraphError> {
364	    if exists_on_path("python3", path_value) {
365	        Ok("python3")
366	    } else if exists_on_path("python", path_value) {
367	        Ok("python")
368	    } else {
369	        Err(GraphError::ReleasePreconditionUnmet {
370	            requirement: ReleasePreconditionRequirement::PythonInterpreterOnPath,
371	        })
372	    }
373	}
