160	    /// Re-hashes the files about to be uploaded: a sealed file changed after verification must not reach the index.
161	    pub(super) fn recheck(&self, files: &[&BuiltFile]) -> Result<(), GraphError> {
162	        if !self.sealed {
163	            return Ok(());
164	        }
165	        for file in files {
166	            let metadata = std::fs::symlink_metadata(&file.path).map_err(io_error)?;
167	            let bytes = std::fs::read(&file.path).map_err(io_error)?;
168	            if !metadata.is_file() || format!("{:x}", Sha256::digest(bytes)) != file.sha256 {
169	                return Err(GraphError::ArtifactBytesMismatch {
170	                    path: file.path.clone(),
171	                });
172	            }
173	        }
174	        Ok(())
175	    }
