243	/// Presence is by filename. A sealed set compares every digest; otherwise only files this run uploaded, as a
244	/// rebuild need not match an earlier attempt.
245	pub(super) fn compare<'a>(set: &'a BuiltSet, remote: &'a [PypiSimpleFile]) -> Comparison<'a> {
246	    let uploaded = set.uploaded();
247	    let mut comparison = Comparison::default();
248	    for file in &set.files {
249	        match remote.iter().find(|candidate| candidate.filename == file.filename) {
250	            None => comparison.missing.push(&file.filename),
251	            Some(held) if held.is_yanked() => comparison.yanked.push(&file.filename),
252	            Some(held) => {
253	                let unconfirmed = if set.sealed {
254	                    held.sha256() != Some(file.sha256.as_str())
255	                } else {
256	                    uploaded.contains(&file.filename) && held.sha256().is_some_and(|digest| digest != file.sha256)
257	                };
258	                if unconfirmed {
259	                    comparison.differing.push(&file.filename);
260	                }
261	            }
262	        }
263	    }
264	    comparison.extras = remote
265	        .iter()
266	        .map(|held| held.filename.as_str())
267	        .filter(|name| set.files.iter().all(|file| file.filename != *name))
268	        .collect();
269	    comparison
270	}
