103	/// Verifies every manifest entry against the exact artifact directory.
104	///
105	/// The artifact directory and every candidate are canonicalized, and symbolic
106	/// links are rejected, so a manifest asset name cannot escape the supplied
107	/// build-output directory. Each asset is streamed once for a bounded-memory
108	/// SHA-256 and size comparison. `gh attestation verify` then validates the
109	/// repository, workflow path and commit, source commit, and hosted-runner
110	/// policy declared by the immutable artifact slot.
111	pub fn verify_artifact_manifest<'a, R: CommandRunner>(
112	    intent: &ReleaseIntentV1,
113	    manifest: &'a ArtifactManifestV1,
114	    artifact_root: &Path,
115	    runner: &R,
116	) -> Result<VerifiedArtifactManifest<'a>, GraphError> {
117	    manifest
118	        .validate_for_intent(intent)
119	        .map_err(|source| GraphError::ArtifactManifest { source })?;
120	
121	    let root = canonical_artifact_root(artifact_root)?;
122	    for entry in &manifest.entries {
123	        let path = resolve_asset_path(&root, &entry.slot.asset_name)?;
124	        let file = File::open(&path).map_err(|error| GraphError::ArtifactRead {
125	            path: path.clone(),
126	            message: error.to_string(),
127	        })?;
128	        let (digest, length) =
129	            callisto_model::ArtifactDigest::from_reader(file).map_err(|error| GraphError::ArtifactRead {
130	                path: path.clone(),
131	                message: error.to_string(),
132	            })?;
133	        if digest != entry.digest || length != entry.byte_length {
134	            return Err(GraphError::ArtifactBytesMismatch { path });
135	        }
136	
137	        verify_github_attestation(&path, entry, runner)?;
138	    }
139	    for file in manifest.distributions.iter().flat_map(|set| &set.files) {
140	        let path = resolve_asset_path(&root, &file.filename)?;
141	        let opened = File::open(&path).map_err(|error| GraphError::ArtifactRead {
142	            path: path.clone(),
143	            message: error.to_string(),
144	        })?;
145	        let (digest, length) =
146	            callisto_model::ArtifactDigest::from_reader(opened).map_err(|error| GraphError::ArtifactRead {
147	                path: path.clone(),
148	                message: error.to_string(),
149	            })?;
150	        if digest != file.digest || length != file.byte_length {
151	            return Err(GraphError::ArtifactBytesMismatch { path });
152	        }
153	    }
154	    Ok(VerifiedArtifactManifest { manifest, root })
