 80	    // A receipt records only full success; a partial run is recovered by rerunning.
 81	    if let Some(path) = &receipt {
 82	        callisto_model::atomic::probe_atomic_write(path, &permit).map_err(|source| CliError::Io {
 83	            source,
 84	            path: Some(path.clone()),
 85	        })?;
 86	    }
 87	    let callisto_model::SourceIdentity::GitCommit { sha } = &intent.snapshot.source else {
 88	        return Err(CliError::ReleaseEnvelopeInvalid {
 89	            detail: "a local release source must be a Git commit".to_owned(),
 90	        });
 91	    };
 92	    // A local run is its own orchestration, so both revisions are the source commit.
 93	    let envelope =
 94	        ReleaseRunEnvelopeV1::new(sha.clone(), &intent, None).map_err(|error| CliError::ReleaseEnvelopeInvalid {
 95	            detail: error.to_string(),
 96	        })?;
 97	    let capability = validate_local_release_intent(&root, &locator, &runner, intent)?;
 98	    let state = execute_release(&capability, &permit, &envelope, None)?;
 99	    let receipt_document =
100	        ReleaseReceiptV1::from_state(capability.intent(), &state).map_err(|error| CliError::ReleaseReceiptIssue {
101	            detail: error.to_string(),
102	        })?;
103	    if let Some(path) = &receipt {
104	        write_receipt(path, &receipt_document, &permit)?;
105	    }
106	    match global.format {
107	        OutputFormat::Json => emit_report(
108	            &mut std::io::stdout(),
109	            &ReleaseReport {
110	                receipt: receipt_document.clone(),
111	            },
112	            global.dry_run,
113	        )?,
114	        OutputFormat::Text => {
115	            let released = capability.intent().decision.entries.len();
116	            match &receipt {
117	                Some(path) => emit_line(&format!(
118	                    "Released {released} package(s); receipt saved to {}",
119	                    path.display()
120	                ))?,
121	                None => emit_line(&format!("Released {released} package(s)"))?,
122	            }
123	        }
124	    }
125	    Ok(ExitCode::SUCCESS)
126	}
