205	fn describe_operation(operation: &callisto_model::ReleaseOperation) -> String {
206	    match &operation.id().role {
207	        callisto_model::ReleaseOperationRole::RegistryPublish { registry } => {
208	            format!("publish to {}", registry.registry_key().display_name())
209	        }
210	        callisto_model::ReleaseOperationRole::PlatformPublish { registry, platform } => {
