212	                "publish {} to {}",
213	                platform.name(),
214	                registry.registry_key().display_name()
215	            )
216	        }
217	        callisto_model::ReleaseOperationRole::Tag => "create git tag".to_owned(),
218	        callisto_model::ReleaseOperationRole::ForgeRelease => "create GitHub release draft".to_owned(),
219	        callisto_model::ReleaseOperationRole::ArtifactUpload { slot } => {
220	            format!("upload {}", slot.asset_name)
221	        }
