227	///
228	/// `use_color` is the one color/table decision ([`crate::color::enabled`]):
229	/// box-drawing table formatting renders only alongside color, never independently.
230	fn render_release_plan(intent: &ReleaseIntentV1, use_color: bool) -> String {
231	    let mut out = String::from("Release plan:\n");
232	    if use_color {
233	        out.push_str(&render_release_plan_table(intent));
234	        return out;
235	    }
236	    for entry in &intent.decision.entries {
237	        out.push_str(&format!("  {} {}\n", entry.package, entry.target_version));
238	        for operation in intent.operations.iter().filter(|op| op.id().package == entry.package) {
239	            out.push_str(&format!("    - {}\n", describe_operation(operation)));
240	        }
241	    }
242	    out
243	}
