152	/// The pending operations whose every transitive prerequisite is exactly
153	/// `Published` or `AlreadySatisfied`, in the intent's canonical order.
154	pub(crate) fn eligible_operations(
155	    intent: &ReleaseIntentV1,
156	    state: &ReleaseExecutionStateV1,
157	) -> Vec<ReleaseOperationId> {
158	    let prerequisites: BTreeMap<_, _> = intent
159	        .operations
160	        .iter()
161	        .map(|operation| (operation.id().clone(), operation.prerequisites().to_vec()))
162	        .collect();
163	    let mut satisfied = BTreeMap::new();
164	    intent
165	        .operations
166	        .iter()
167	        .filter(|operation| state.operation_state(operation.id()) == Some(OperationState::Pending))
168	        .filter(|operation| {
169	            prerequisites_satisfied_transitively(
170	                operation.id(),
171	                &prerequisites,
172	                state,
173	                &mut BTreeSet::new(),
174	                &mut satisfied,
175	            )
176	        })
177	        .map(|operation| operation.id().clone())
178	        .collect()
179	}
