104	impl InitFacts {
105	    pub fn binary_packages(&self) -> impl Iterator<Item = &InitPackage> {
106	        self.packages
107	            .iter()
108	            .filter(|package| package.is_binary() && package.supports_artifact_builder())
109	    }
