67	pub fn napi_drift(group: &GroupDef, declared: &[String], root: &Path) -> Vec<Diagnostic> {
68	    use crate::config::groups::GroupMemberKind;
69	
70	    let declared_triples: BTreeSet<String> = declared.iter().map(|s| s.trim().to_string()).collect();
71	
72	    let member_triples: BTreeSet<String> = group
73	        .members(GroupMemberKind::PlatformManifest)
74	        .filter_map(|m| match m {
75	            GroupMember::PlatformManifest { role, .. } => role_to_triple(role),
76	            _ => None,
77	        })
78	        .collect();
79	
80	    let mut diagnostics = Vec::new();
81	
82	    // Declared in napi.targets but no corresponding group member.
83	    for t in declared_triples.difference(&member_triples) {
84	        diagnostics.push(Diagnostic {
85	            code: DiagnosticCode::NapiTargetAddedNotInMembers,
86	            severity: DiagnosticSeverity::Warning,
87	            message: format!(
88	                "`napi.targets` declares `{t}`, which is not in fixed group `{}`'s members; accept it with `callisto init`",
89	                group.name
90	            ),

160	    ctx: &OpenContext<'_>,
161	) -> Result<Identified, GraphError> {
162	    let Discovered {
163	        by_path,
164	        attached_platforms,
165	    } = discovered;
166	    let mut assigner = IdentityAssigner::new(manifest_cache, ctx);
167	    for (rel_path, list) in by_path {
168	        if attached_platforms.contains_key(&rel_path) {
169	            continue;
170	        }
171	        assigner.assign(rel_path, list)?;
172	    }
173	    assigner.attach_platforms(attached_platforms);
174	    Ok(assigner.finish())
175	}
