177	/// The order-dependent identity assignment: whether a path's identity is bare or ecosystem-prefixed depends on the
178	/// names seen in earlier paths, so this is one incremental pass that owns all of its bookkeeping.
179	struct IdentityAssigner<'a> {
180	    manifest_cache: &'a RefCell<BTreeMap<PathBuf, Arc<dyn Manifest>>>,
181	    ctx: &'a OpenContext<'a>,
182	    package_manifest_decls: BTreeMap<PackageId, (PathBuf, Vec<ManifestDecl>)>,
183	    index: IdentityIndex,
184	    claiming_ecosystems: BTreeMap<PathBuf, BTreeSet<Ecosystem>>,
185	    // Every (ecosystem, native name) any path declares, anywhere in that path's
186	    // manifest list -- not only its primary name -- belongs to exactly one directory.
187	    native_owner: BTreeMap<(Ecosystem, String), PathBuf>,
188	    path_native_keys: BTreeMap<PathBuf, Vec<(Ecosystem, String)>>,
189	    path_platform_keys: BTreeMap<PathBuf, Vec<String>>,
190	    primary_ecosystems: BTreeMap<PathBuf, Ecosystem>,
191	    promoted_siblings: BTreeMap<String, Vec<(PackageId, BTreeSet<Ecosystem>)>>,
192	}
193	
194	impl<'a> IdentityAssigner<'a> {
195	    fn new(manifest_cache: &'a RefCell<BTreeMap<PathBuf, Arc<dyn Manifest>>>, ctx: &'a OpenContext<'a>) -> Self {
196	        IdentityAssigner {
197	            manifest_cache,
198	            ctx,
199	            package_manifest_decls: BTreeMap::new(),
200	            index: IdentityIndex::default(),
201	            claiming_ecosystems: BTreeMap::new(),
202	            native_owner: BTreeMap::new(),
203	            path_native_keys: BTreeMap::new(),
204	            path_platform_keys: BTreeMap::new(),
205	            primary_ecosystems: BTreeMap::new(),
206	            promoted_siblings: BTreeMap::new(),
207	        }
208	    }
209	
210	    fn assign(&mut self, rel_path: PathBuf, mut list: Vec<(Ecosystem, PackageId)>) -> Result<(), GraphError> {
211	        // Explicit precedence: Cargo (0) > Npm (1) > Pypi (2) > others.
212	        // Do NOT rely on enum discriminant order -- sort by this named
213	        // priority function so the precedence survives future variant
214	        // additions to `Ecosystem`.
215	        list.sort_by_key(|a| ecosystem_primary_priority(a.0));
216	
217	        // E100 whenever any (ecosystem, native name) this path declares -- primary
218	        // or not -- is already owned by a different path; names both. Checked before
219	        // any promotion bookkeeping so a dual-manifest directory's non-primary name
220	        // (e.g. an npm sibling of a Cargo-primary package) is covered too, not just
221	        // each path's own primary name.
222	        if let Some((eco, id)) = list.iter().find(|(eco, id)| {
