652	    // Cross-ecosystem diagnostic pass.
653	    //
654	    // For each bare [[package]] rule in cfg.packages (pattern.ecosystem() == None),
655	    // compute the distinct-ecosystem set: the Ecosystem values found in the canonical
656	    // ManifestDecls of every packages-map entry matched by this rule.
657	    //
658	    // Packages-map keys may be PackageId::Bare or PackageId::Prefixed (a
659	    // promoted package). This loop
660	    // remains correct regardless: ecosystem information is always sourced from
661	    // pkg.canonical_manifests(), never from key.ecosystem(), and `pattern`
662	    // here is always unprefixed (prefixed rules `continue` above), so
663	    // pattern.matches(key) matches by name alone independent of whether `key`
664	    // itself is Bare or Prefixed. Do NOT use key.ecosystem().
665	    //
666	    // The primary trigger is a single directory containing both Cargo.toml and
667	    // package.json (the napi case): one packages-map entry with two canonical
668	    // ManifestDecls whose ecosystems are {Cargo, Npm}.
669	    //
670	    // Prefixed [[package]] rules are skipped unconditionally.
671	    // [[package-set]] rules are never iterated here.
672	    for (pattern, _) in &cfg.packages {
673	        if pattern.ecosystem().is_some() {
674	            continue; // Prefixed rules never trigger this diagnostic.
675	        }
676	        let ecosystems: BTreeSet<Ecosystem> = packages
677	            .iter()
678	            .filter(|(key, _)| pattern.matches(key))
679	            // Use the existing Package::canonical_manifests() helper
680	            // (package.rs) which filters to ManifestRole::Canonical.
681	            .flat_map(|(_, pkg)| pkg.canonical_manifests().map(|d| d.ecosystem()))
682	            .collect();
683	        if ecosystems.len() >= 2 {
684	            let eco_list: Vec<&str> = ecosystems.iter().map(|e| e.prefix()).collect();
685	            diagnostics.push(Diagnostic {
686	                code: DiagnosticCode::BareRuleMatchesMultipleEcosystems,
687	                severity: DiagnosticSeverity::Warning,
688	                message: format!(
689	                    "[[package]] rule `{}` matches packages in multiple ecosystems ({}); \
690	                         use an ecosystem-prefixed pattern like `{}/{}` to target only one",
691	                    pattern.name(),
692	                    eco_list.join(", "),
693	                    ecosystems.iter().next().map(|e| e.prefix()).unwrap_or("cargo"),
694	                    pattern.name(),
695	                ),
696	                package: None,
697	                path: None,
698	                escalated_by: None,
699	                governed_by: None,
700	            });
701	        }
702	    }
703	
704	    Ok(packages)
705	}
