772	/// Renders `target` at the precision a rewritten spec should carry, for use after `op`:
773	/// `major.minor.patch` for a stable release; the version in full for a pre-release or
774	/// dev target paired with `==`/`!=` (the only operators PEP 440 allows on a local version);
775	/// the version with its local segment stripped for every other operator, since PEP 440
776	/// forbids `>=`, `<=`, `>`, `<` and `~=` from carrying one.
777	fn render_target(op: &str, target: &Version) -> Option<String> {
778	    if target.is_prerelease() {
779	        let full = target.render();
780	        if op == "==" || op == "!=" {
781	            return Some(full.to_string());
782	        }
783	        return Some(full.split('+').next().unwrap_or(full).to_string());
784	    }
785	    Some(format!("{}.{}.{}", target.major()?, target.minor()?, target.patch()?))
786	}
787	
788	/// Rewrites a two-clause `>=X.Y.Z,<A.B` range to `>=NEW,<NEXT_MAJOR`.
789	///
790	/// Returns `None` for anything that does not match exactly this two-clause
791	/// lower/upper pattern, including specs with three or more clauses (e.g.
792	/// `>=1.0,<2.0,!=1.5.0`) where silently dropping extra clauses would produce
793	/// a semantically incorrect constraint.
794	fn rewrite_range(original: &str, target: &Version) -> Option<DepSpec> {
795	    // Reject any spec with more than two comma-separated clauses: rewriting
796	    // would silently discard the extra clauses, changing the semantics.
797	    if original.split(',').count() != 2 {
798	        return None;
799	    }
800	
801	    let mut parts = original.splitn(2, ',');
802	    let lower = parts.next()?.trim();
803	    let upper = parts.next()?.trim();
804	
805	    // Lower clause must be `>=…`.
806	    if !lower.starts_with(">=") {
807	        return None;
808	    }
809	    // Upper clause must be strictly `<…` (not `<=`).
810	    if !upper.starts_with('<') || upper.starts_with("<=") {
811	        return None;
812	    }
813	
814	    let next_major = target.major()? + 1;
815	    let rendered = format!(">={},<{next_major}", render_target(">=", target)?);
816	    let req = VersionReq::parse(&rendered, Ecosystem::Pypi).ok()?;
817	    Some(DepSpec::Range(req, rendered))
818	}
