832	/// One PEP 508 requirement string as a dependency edge, or `None` when it names no package.
833	fn pep508_entry(full_req_str: &str, kind: DepKind, locator: DepLocator) -> Option<DependencyEntry> {
834	    // `Requirement::parse` couldn't extract even a package name (an empty string or a
835	    // marker-only fragment): there is no name to key an entry on.
836	    let req = Requirement::parse(full_req_str)?;
837	    let req_str = req.spec.clone().unwrap_or_else(|| "*".to_string());
838	    let parsed_req_str = req.spec.as_deref().unwrap_or(">=0.0.0");
839	    let spec = match VersionReq::parse(parsed_req_str, Ecosystem::Pypi) {
840	        Ok(spec) => DepSpec::Range(spec, req_str),
841	        // A PEP 508 clause `pep440_rs` can't parse (exotic or malformed syntax): keep the
842	        // dependency visible in the graph rather than silently dropping it.
843	        Err(_) => DepSpec::Opaque(req_str),
844	    };
845	    Some(DependencyEntry {
846	        name: req.name.clone(),
847	        package_name: req.name.clone(),
848	        inherited: false,
849	        kind,
850	        spec,
851	        locator,
852	    })
853	}
