290	        .iter()
291	        .map(|set| (set.package.clone(), set.version.clone()))
292	        .ne(expected
293	            .iter()
294	            .map(|(package, version)| ((*package).clone(), version.clone())))
295	    {
296	        return Err(ArtifactManifestError::MismatchedDistributionRoster);
297	    }
298	    let mut names: Vec<&str> = entries.iter().map(|entry| entry.slot.asset_name.as_str()).collect();
299	    for set in distributions {
300	        let files = || set.files.iter().map(|file| file.filename.as_str());
301	        if files().any(|name| !is_safe_artifact_component(name)) {
302	            return Err(ArtifactManifestError::UnsafeDistributionFile);
303	        }
304	        if !files().any(is_wheel) || !files().any(is_sdist) {
305	            return Err(ArtifactManifestError::IncompleteDistributionSet);
306	        }
307	        names.extend(files());
308	    }
309	    names.sort_unstable();
310	    if names.windows(2).any(|pair| pair[0] == pair[1]) {
311	        return Err(ArtifactManifestError::DuplicateDistributionFile);
312	    }
