 67	pub fn status<R: CommandRunner, D: DependencyResolver, I: SeverityInference>(
 68	    ws: &Workspace<'_, R, D>,
 69	    inference: &I,
 70	    opts: &StatusOptions,
 71	) -> Result<StatusReport, GraphError> {
 72	    let mut packages = Vec::new();
 73	    let base_versions = ws.base_versions()?;
 74	    let (loaded_changesets, changeset_load_failures) = crate::load_changesets_permissive(&ws.root, &ws.config)?;
 75	    let tags = ws.tags()?;
 76	
 77	    let all_packages: Vec<&Package> = ws.graph.packages().collect();
 78	    let pending = resolve_pending_changesets(all_packages.iter().copied(), &ws.identity, &loaded_changesets)?;
 79	
 80	    // Pending severity is `plan_version`'s own
 81	    // `PlannedBump.severity` per package -- the same cascade/fixed/linked-group
 82	    // computation `callisto version` uses. status computes no cascade of its
 83	    // own; it only reads the plan `plan_version` already derives.
 84	    let version_opts = VersionOptions {
 85	        strict: opts.strict,
 86	        allow_empty_changesets: true,
 87	    };
 88	    // An ambiguous changeset entry, or an unparseable changeset file, makes `plan_version`
 89	    // (via `aggregate`'s own strict `load_changesets`) hard-error -- the right behavior for a
 90	    // real `version`/`release` run, but `status` must survive both and report
 91	    // `AmbiguousPackageName`/the parse failure diagnostic below instead. Severity planning is
 92	    // skipped for this run rather than duplicating `aggregate`'s own resolution to route
 93	    // around its error.
 94	    let plan = match plan_version(ws, inference, &version_opts) {
 95	        Ok(plan) => Some(plan),
 96	        Err(GraphError::AmbiguousName { .. } | GraphError::ParseChangeset { .. }) => None,
 97	        Err(e) => return Err(e),
 98	    };
 99	    let planned_severity: BTreeMap<PackageId, Severity> = plan
100	        .iter()
101	        .flat_map(|plan| &plan.bumps)
102	        .map(|b| (b.package.clone(), b.severity))
103	        .collect();
104	
105	    let changed = changed_since_last_tag(&all_packages, tags, ws.git_access())?;
106	
107	    for pkg in all_packages.iter().copied() {
108	        let current_version = base_versions.get(&pkg.id).cloned().ok_or_else(|| {
109	            GraphError::Manifest(callisto_model::ManifestError::MissingField {
110	                path: pkg.manifests.first().map(|m| m.path.clone()).unwrap_or_default(),
111	                field: "version",
112	            })
113	        })?;
114	        let last = tags.last_tag(&pkg.id);
115	        let last_tag = last.map(|t| t.name.clone());
116	        let last_released_version = last.map(|t| t.version.clone());
117	
118	        let (pkg_changesets, _) = pending.get(&pkg.id).cloned().unwrap_or_default();
119	        let pending_severity = planned_severity.get(&pkg.id).copied();
120	
121	        packages.push(callisto_model::StatusPackageRecord {
122	            package: pkg.id.clone(),
123	            current_version,
124	            last_tag,
125	            last_released_version,
126	            pending_severity,
127	            changed_since_last_tag: changed[&pkg.id],
128	            release_trigger: pkg.release_trigger,
129	            pending_changesets: pkg_changesets,
130	        });
131	    }
132	
133	    let mut diagnostics = ws.graph.diagnostics().to_vec();
134	    // Fold in every well-formedness diagnostic `validate` used to
135	    // report (EmptyChangeset, UnknownPackage, AmbiguousPackageName,
136	    // InvalidPackageName) now that `validate` is gone.
137	    diagnostics.extend(changeset_wellformedness_diagnostics(
138	        all_packages.iter().copied(),
139	        &ws.identity,
140	        &loaded_changesets,
141	    )?);
142	    for failure in &changeset_load_failures {
143	        diagnostics.push(Diagnostic {
144	            code: DiagnosticCode::ChangesetParseFailed,
145	            severity: DiagnosticSeverity::Error,
146	            message: format!("{}: {}", failure.path.display(), failure.source),
147	            package: None,
148	            path: Some(failure.path.clone()),
149	            governed_by: None,
150	            escalated_by: None,
151	        });
152	    }
153	    escalate(&mut diagnostics, opts.strict);
154	
155	    let has_changesets = packages.iter().any(|p| !p.pending_changesets.is_empty());
156	    // Count of packages with a planned bump, post-cascade/fixed/linked-group --
157	    // the field a script now reads to detect pending changesets, since `--check`'s
158	    // exit code no longer signals it.
159	    let pending = packages.iter().filter(|p| p.pending_severity.is_some()).count() as u32;
160	
161	    Ok(StatusReport {
162	        schema_version: SCHEMA_VERSION,
163	        has_changesets,
164	        pending,
165	        packages,
166	        diagnostics,
167	    })
168	}
