170	/// The per-changeset well-formedness diagnostics `validate` used to emit
171	/// (crates/callisto-graph/src/commands/validate.rs, now removed): entries shape and
172	/// package-name resolution. Resolves through the same identity index
173	/// `resolve_pending_changesets` does, but this scan must never abort early,
174	/// so an unknown or ambiguous entry becomes a diagnostic instead of an
175	/// early return.
176	///
177	/// An entries-empty changeset is advisory only (`Info`): `@changesets/cli add --empty`
178	/// produces one deliberately, so it is not a well-formedness problem. A changeset with
179	/// entries but an empty summary never reaches this scan at all -- `load_changesets_permissive`
180	/// already rejects that shape at parse time, surfacing it as a `ChangesetParseFailed`
181	/// diagnostic instead.
182	fn changeset_wellformedness_diagnostics<'a>(
183	    packages: impl Iterator<Item = &'a Package> + Clone,
184	    identity: &IdentityIndex,
185	    loaded: &[LoadedChangeset],
186	) -> Result<Vec<Diagnostic>, GraphError> {
187	    let mut diagnostics = Vec::new();
188	    for cs in loaded {
189	        if cs.changeset.entries.is_empty() {
190	            diagnostics.push(Diagnostic {
191	                code: DiagnosticCode::EmptyChangeset,
192	                severity: DiagnosticSeverity::Info,
193	                message: format!("Changeset `{}` is empty", cs.path.display()),
194	                package: None,
195	                path: Some(cs.path.clone()),
196	                governed_by: None,
197	                escalated_by: None,
198	            });
199	        }
200	
201	        for entry in &cs.changeset.entries {
202	            match PackageId::parse(&entry.name) {
203	                Ok(id) => match resolve_target_package(packages.clone(), identity, &id) {
204	                    Ok(None) => {
205	                        diagnostics.push(Diagnostic {
206	                            code: DiagnosticCode::UnknownPackage,
207	                            severity: DiagnosticSeverity::Error,
208	                            message: format!(
209	                                "Changeset `{}` references unknown package `{}`",
210	                                cs.path.display(),
211	                                entry.name
212	                            ),
213	                            package: Some(id),
214	                            path: Some(cs.path.clone()),
215	                            governed_by: None,
216	                            escalated_by: None,
217	                        });
218	                    }
219	                    Ok(Some(_)) => {}
220	                    Err(GraphError::AmbiguousName { candidates, .. }) => {
221	                        let names: Vec<String> = candidates.iter().map(|id| id.display_name().to_string()).collect();
222	                        diagnostics.push(Diagnostic {
223	                            code: DiagnosticCode::AmbiguousPackageName,
224	                            severity: DiagnosticSeverity::Error,
225	                            message: format!(
226	                                "Changeset `{}` references ambiguous package `{}` (matches: {})",
227	                                cs.path.display(),
228	                                entry.name,
229	                                names.join(", ")
230	                            ),
231	                            package: Some(id),
232	                            path: Some(cs.path.clone()),
233	                            governed_by: None,
234	                            escalated_by: None,
235	                        });
236	                    }
237	                    Err(e) => return Err(e),
238	                },
239	                Err(_) => {
240	                    diagnostics.push(Diagnostic {
