            self.native_owner
                .get(&(*eco, id.name().to_string()))
                .is_some_and(|p| *p != rel_path)
        }) {
            let owner_path = self.native_owner[&(*eco, id.name().to_string())].clone();
            return Err(GraphError::DuplicatePackage {
                id: id.clone(),
                paths: vec![owner_path, rel_path],
            });
        }
