        let mut bumps = Vec::new();
        for b in &self.bumps {
            bumps.push(BumpRecord {
                package: b.package.clone(),
                from: b.from.clone(),
                to: b.to.clone(),
                severity: b.severity,
                governed_by: b.governed_by.clone(),
                reason: b.reason.clone(),
            });
        }

        VersionReport {
