/// rather than a `dry_run` bool: a bool carries no guarantee any caller
/// actually consulted it. A dry-run caller can't obtain a permit and
/// simply doesn't call this function; it reports `plan` instead.
///
/// # Errors
///
/// - Manifest parse/write failures (malformed TOML/JSON, unsupported format).
/// - Git subprocess failures (`git add`/`git rm --cached` non-zero exit).
/// - I/O errors writing changelog sections or `pre.json`.
pub fn apply_version_plan<R: CommandRunner>(
    root: &Path,
    plan: &VersionPlan,
    runner: &R,
    opts: &ApplyOptions,
    permit: &ApplyPermit,
) -> Result<ApplyOutcome, GraphError> {
    let mut outcome = ApplyOutcome::default();
    let mut modified_paths = Vec::new();
    let mut deferred_deletions = Vec::new();

    let ctx = OpenContext::for_workspace_root(root);

    let classification = classify_manifest_writes(plan);

    for (path, group) in &classification.batched {
        let fmt = callisto_model::ManifestFormat::from_path(path)?;
        let decl = callisto_model::ManifestDecl::new(path.clone(), ManifestRole::Canonical, fmt)?;
        let mut handle = open(&decl, &ctx)?;
        let mut mutated = false;

        if let Some((bump_idx, target_version)) = &group.bump {
            let bump = &plan.bumps[*bump_idx];
            let current = handle.current_version()?;
            if current == *target_version {
                // Already at target — skip write, fall through to rewrites.
            } else if current == bump.from {
                handle.write_version(target_version, permit)?;
                mutated = true;
            } else {
                return Err(GraphError::UnexpectedManifestVersion {
                    path: path.clone(),
                    expected_from: bump.from.clone(),
                    expected_to: bump.to.clone(),
                    found: current,
                });
            }

    /// --list` spawn. Several command paths never consult tags at all (`add`'s
    /// non-interactive path only needs [`Workspace::root`]; `init` only
    /// needs package names/root), so building unconditionally in
    /// `Workspace::load` charged every caller for work only some need. All
    /// of `TagIndex::build`'s inputs are already `Workspace` fields, so a
    /// `OnceCell` needs no extra state -- go through [`Workspace::tags`],
    /// not this field directly.
    pub tags: OnceCell<TagIndex>,
    /// Deferred [`GitAccess`], built the first time [`Workspace::git_access`]
    /// is called. `pub` so tests can hand-construct a `Workspace` with a
    /// pre-seeded value.
    pub git: OnceCell<GitAccess<'a>>,
    pub runner: &'a R,
    /// Path-keyed cache of manifest handles opened read-only during this
    /// workspace's lifetime. Populated during graph discovery
    /// (`ManifestWalkResolver::build`) and reused by read-only accessors
    /// such as [`Workspace::base_versions`] so a given manifest is opened
    /// (read + parsed) at most once per command run. Never consulted by the
    /// manifest-open-for-write path in `apply.rs`, which always needs a
    /// fresh, exclusively-owned `&mut` handle.
    pub manifest_cache: RefCell<BTreeMap<PathBuf, Arc<dyn Manifest>>>,
    pub identity: IdentityIndex,
}

impl<'a, R: CommandRunner> Workspace<'a, R, ManifestWalkResolver> {
    pub fn load<L: ProjectLocator>(root: PathBuf, locator: &L, runner: &'a R) -> Result<Self, GraphError> {
        let config = config::load(&root)?;
        Self::load_with_config(root, config, locator, runner)
    }

    /// Builds the workspace against an already-resolved config instead of `callisto.toml`.
    pub fn load_with_config<L: ProjectLocator>(
        root: PathBuf,
        mut config: ResolvedConfig,
        locator: &L,
        runner: &'a R,
    ) -> Result<Self, GraphError> {
        let manifest_cache: RefCell<BTreeMap<PathBuf, Arc<dyn Manifest>>> = RefCell::new(BTreeMap::new());
        let graph = ManifestWalkResolver::build(&root, locator, runner, &config, &manifest_cache)?;

        config.groups = GroupTable::resolve(&config.raw_groups, graph.identity())?;

        {
            let mut by_name: BTreeMap<String, Vec<(PackageId, BTreeSet<Ecosystem>)>> = BTreeMap::new();
            let mut ecosystems_by_id: BTreeMap<(String, PackageId), BTreeSet<Ecosystem>> = BTreeMap::new();
            for ((eco, name), id) in &graph.identity().prefixed {
                ecosystems_by_id
                    .entry((name.clone(), id.clone()))
                    .or_default()
                    .insert(*eco);
            }
            for ((name, id), ecos) in ecosystems_by_id {
                by_name.entry(name).or_default().push((id, ecos));
            }
            config.promoted_siblings = by_name.into_iter().filter(|(_, ids)| ids.len() >= 2).collect();
        }

        let identity = graph.identity().clone();

        Ok(Workspace {
            root,
            config,
            graph,
            tags: OnceCell::new(),
            git: OnceCell::new(),
            runner,
            manifest_cache,
            identity,
        })
    }
}

impl<'a, R: CommandRunner, D: DependencyResolver> Workspace<'a, R, D> {
    /// Returns the workspace's [`TagIndex`], building it on first access and
    /// reusing the cached result afterwards. See the doc comment on the
    /// `tags` field for why this is deferred rather than built eagerly by
    /// [`Workspace::load`].
    pub fn tags(&self) -> Result<&TagIndex, GraphError> {
        if let Some(existing) = self.tags.get() {
            return Ok(existing);
        }
        let built = TagIndex::build(self.git_access(), &self.graph, &self.config)?;
        // `OnceCell::set` only fails if another write already raced it in;
        // `Workspace` is only ever accessed through `&self` here (never
        // shared across threads -- `R`/`D` carry no such bound), so the
        // `get()` check above already ruled that out. Fall back to `get()`
        // either way rather than trusting the `set` call's own return value,
        // so this stays correct even if that assumption ever changes.
        self.tags.set(built).ok();
        Ok(self
            .tags
            .get()
            .expect("tags was just set above, or already set by a prior call"))
    }

    /// Returns the workspace's shared [`GitAccess`], rooted at the workspace
    /// root and running `git` through the workspace's runner.
    pub fn git_access(&self) -> &GitAccess<'a> {
        self.git.get_or_init(|| GitAccess::new(&self.root, self.runner))
    }

    /// Top-level key whose co-presence with the workspace table marks a
    /// hybrid root, e.g. `"package"` for Cargo or `"project"` for Python.
    owner_key: &'static str,
}

pub(crate) const CARGO_MEMBERSHIP_SPEC: MembershipSpec = MembershipSpec {
    manifest_file_name: ManifestFormat::CargoToml.file_name(),
    table_path: &["workspace"],
    owner_key: "package",
};

pub(crate) const PYTHON_MEMBERSHIP_SPEC: MembershipSpec = MembershipSpec {
    manifest_file_name: ManifestFormat::PyprojectToml.file_name(),
    table_path: &["tool", "uv", "workspace"],
    owner_key: "project",
};

/// NAIVE first pass: only handles (1) the manifest file entirely absent, and
/// (2) a well-formed workspace table with members/exclude arrays of
/// strings. Every other shape (workspace table absent, TOML unparseable,
/// members/exclude present but not an array-of-strings, members key
/// absent) falls back to an absent-filter (admit-all) result -- see the
/// `cargo_membership_tests`/`python_membership_tests` modules for the
/// exact fallback matrix this is pinned against.
pub(crate) fn read_membership(root: &Path, spec: &MembershipSpec) -> Membership {
    let content = match std::fs::read_to_string(root.join(spec.manifest_file_name)) {
        Ok(c) => c,
        Err(_) => return Membership::absent(),
    };
    let doc = match content.parse::<toml_edit::DocumentMut>() {
        Ok(d) => d,
        Err(_) => return Membership::absent(),
    };

    let mut cursor: Option<&toml_edit::Item> = doc.get(spec.table_path[0]);
    for key in &spec.table_path[1..] {
        cursor = cursor.and_then(|c| c.get(*key));
    }

    let hybrid_root = doc.get(spec.owner_key).is_some() && cursor.is_some();
    let Some(workspace) = cursor else {
        return Membership {
            members: None,
            exclude: NegatableGlobSet::empty(),
            hybrid_root,
        };
    };
    let members = workspace
        .get("members")
        .and_then(parse_toml_string_array)
        .map(|v| build_globset(&v));
    let exclude = workspace
        .get("exclude")
        .and_then(parse_toml_string_array)
        .map(|v| build_globset(&v))
        .unwrap_or_else(NegatableGlobSet::empty);
    Membership {
        members,
        exclude,
        hybrid_root,
    }
}

pub(crate) fn read_cargo_membership(root: &Path) -> Membership {
    read_membership(root, &CARGO_MEMBERSHIP_SPEC)
}

