//! Callisto's single disk-write primitive.
//!
//! This lives in Layer 1 (`callisto-model`) rather than alongside the manifest
//! editors because durable file replacement is not a manifest concern: the
//! changelog writer, the pre-mode state file, and the config scaffolder all
//! need it too. Hosting it here means those callers do not have to take a
//! dependency on `callisto-manifests` purely to reach the filesystem.

use std::io::{self, Write};
use std::path::Path;

use crate::ApplyPermit;
use tempfile::NamedTempFile;

/// Durably replaces `path`'s contents with `content`.
///
/// The [`ApplyPermit`] is unused at runtime and exists purely as a compile-time
/// obligation: this is callisto's single disk-write primitive, so requiring a
/// permit here means no code path can reach the filesystem without having first
/// consulted the dry-run flag. See [`crate::permit`].
///
/// # Errors
///
/// Returns the first I/O error encountered: creating parent directories, writing the temp file,
/// flushing, fsyncing, persisting (renaming) to `path`, or syncing the directory that holds it.
pub fn atomic_write(path: &Path, content: &str, permit: &ApplyPermit) -> io::Result<()> {
    let _permit = permit;
    let raw_parent = path.parent().unwrap_or_else(|| Path::new("."));
    let parent = if raw_parent.as_os_str().is_empty() {
        Path::new(".")
    } else {
        raw_parent
    };
    let created_parent = !parent.try_exists()?;
    std::fs::create_dir_all(parent)?;

    let mut temp = temp_file_in(parent)?;
    match_existing_mode(temp.as_file(), path)?;
    temp.write_all(content.as_bytes())?;
    temp.flush()?;
    temp.as_file().sync_all()?;
    temp.persist(path).map_err(|e| e.error)?;

    sync_directory(parent)?;
    // A directory this call created is itself a new entry in its parent.
    if created_parent {
        if let Some(grandparent) = parent.parent().filter(|dir| !dir.as_os_str().is_empty()) {
            sync_directory(grandparent)?;
        }
    }
    Ok(())
}

/// A temp file whose mode follows the process umask like any new file, instead of `tempfile`'s owner-only `0600`.
fn temp_file_in(dir: &Path) -> io::Result<NamedTempFile> {
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        tempfile::Builder::new()
            .permissions(std::fs::Permissions::from_mode(0o666))
            .tempfile_in(dir)
    }
    #[cfg(not(unix))]
    {
        NamedTempFile::new_in(dir)
    }
}

/// Gives the temp file the mode of the file it replaces; a new file keeps the umask-derived mode.
fn match_existing_mode(temp: &std::fs::File, target: &Path) -> io::Result<()> {
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        match std::fs::metadata(target) {
            Ok(existing) => {
                temp.set_permissions(std::fs::Permissions::from_mode(existing.permissions().mode() & 0o7777))
            }
            Err(error) if error.kind() == io::ErrorKind::NotFound => Ok(()),
            Err(error) => Err(error),
        }
    }
    #[cfg(not(unix))]
    {
        let _ = (temp, target);
        Ok(())
    }
}

/// Flushes `dir`'s entries so a rename survives power loss. A directory that cannot be opened (Windows, or a `-wx`
/// mode) or a filesystem that cannot sync one (`Unsupported`, `InvalidInput`, macOS `ENOTSUP`) is skipped: the file is
/// already in place and failing the command now would misreport a write that happened. Any other failure, an I/O error
/// above all, means the rename may not be durable and is reported.
fn sync_directory(dir: &Path) -> io::Result<()> {
    #[cfg(unix)]
    {
        let Ok(handle) = std::fs::File::open(dir) else {
            return Ok(());
        };
        match handle.sync_all() {
            Err(error) if sync_unsupported(&error) => Ok(()),
            result => result,
        }
    }
    #[cfg(not(unix))]
    {
        let _ = dir;
        Ok(())
    }
}

/// Fails now if [`atomic_write`] to `path` could not succeed, leaving no file behind.
/// A pre-existing regular file at `path` is accepted because the write replaces it.
///
/// # Errors
///
/// Returns the I/O error creating the parent directories or a temp file beside `path`, or
/// `IsADirectory`-style `InvalidInput` when `path` is a directory.
pub fn probe_atomic_write(path: &Path, permit: &ApplyPermit) -> io::Result<()> {
    let _permit = permit;
    if path.is_dir() {
        return Err(io::Error::new(
            io::ErrorKind::InvalidInput,
            "destination is a directory",
        ));
    }
    let raw_parent = path.parent().unwrap_or_else(|| Path::new("."));
    let parent = if raw_parent.as_os_str().is_empty() {
        Path::new(".")
    } else {
        raw_parent

    /// `fetch_all_tags`), kept around so callers checking whether a specific
    /// tag name already exists (e.g. the unreleased-version check, once per
    /// package) can consult this in-memory set instead of re-querying `git`
    /// once per check.
    all_tags: std::collections::BTreeSet<String>,
    pub diagnostics: Vec<Diagnostic>,
}

impl TagIndex {
    pub fn build<D: DependencyResolver>(
        git: &GitAccess<'_>,
        graph: &D,
        identity: &IdentityIndex,
        cfg: &ResolvedConfig,
    ) -> Result<Self, GraphError> {
        reject_shared_default_templates(graph)?;
        let mut last = BTreeMap::new();
        let mut templates = BTreeMap::new();
        let mut pre_cursor = BTreeMap::new();
        let mut diagnostics = Vec::new();

        // Fetch the raw tag list exactly once for the whole build, not once
        // per package -- see `fetch_all_tags` for why.
        let all_tags = fetch_all_tags(git)?;
        let all_tags_set: std::collections::BTreeSet<String> = all_tags.iter().cloned().collect();
        let mut glob_cache: std::collections::HashMap<String, Vec<&str>> = std::collections::HashMap::new();

        let mut rosters = crate::history::Rosters::default();

        for pkg in graph.packages() {
            // `TagTemplate::default_for` is the single source of truth for a
            // package's default tag template -- matches `release.rs`'s own
            // `unwrap_or_else(|| callisto_model::TagTemplate::default_for(&package.id))`.
            // Deliberately not `TagTemplate::parse(&format!("{name}@{{version}}"))`:
            // `parse` additionally validates git-ref-name legality, which
            // `default_for` does not, so the two could previously reject/accept a
            // package name differently. Using `default_for` here removes that
            // extra validation from this call site to align with the
            // already-shipped `release.rs` behavior.
            let tmpl = pkg
                .tag_template
                .clone()
                .unwrap_or_else(|| TagTemplate::default_for(&pkg.id));
            let grammar = pkg.version_grammar()?;
            let mut chosen = take_chosen(
                select_from_tags_cached(&all_tags, &tmpl, grammar, &mut glob_cache)?,
                &mut diagnostics,
            );
            if chosen.is_none() {
                let package_ecosystems: Vec<Ecosystem> = pkg.canonical_manifests().map(|m| m.ecosystem()).collect();
                if let Some(previous) =
                    crate::config::resolve::resolve_package_config(&pkg.id, &package_ecosystems, cfg)?
                        .map(|package_config| package_config.previous_tag_templates.as_slice())
                {
                    for template in previous {
                        chosen = take_chosen(
                            select_from_tags_cached(&all_tags, template, grammar, &mut glob_cache)?,
                            &mut diagnostics,
                        );
                        if chosen.is_some() {
                            break;
                        }
                    }
                }
            }
            if chosen.is_none() && pkg.tag_template.is_none() && pkg.id.ecosystem().is_some() {
                // A promoted package keeps the `{name}@` tags it made while its name was unique.
                let unqualified = TagTemplate::default_for(&PackageId::Bare(pkg.id.name().to_string()));
                let same: Vec<&callisto_model::Package> = graph
                    .packages()
                    .filter(|p| p.id.ecosystem().is_some() && p.id.name() == pkg.id.name())
                    .collect();
                let mut owned = Vec::new();
                for tag in matching_tags(&all_tags, &unqualified)? {
                    if crate::history::sole_owner_at(git, tag, pkg.id.name(), &same, identity, &mut rosters)?
                        .is_some_and(|owner| owner.id == pkg.id)
                    {
                        owned.push(tag);
                    }
                }
                chosen = take_chosen(
                    select_last_tag(&unqualified, grammar, owned).map_err(GraphError::from)?,
                    &mut diagnostics,
                );
            }
            if pkg.tag_template.is_none() && pkg.id.ecosystem().is_none() {
                // A demoted package keeps the qualified tags it made while its name was shared.
                if let Some(manifest) = pkg.canonical_manifests().next() {
                    let qualified = TagTemplate::default_for(&PackageId::Prefixed {
                        ecosystem: manifest.ecosystem(),
                        name: pkg.id.name().to_string(),

                    // Reader threads are intentionally not joined here:
                    // if a descendant process is still holding a pipe
                    // fd open, join() could block forever. We wait a
                    // bounded grace period for output, then abandon the
                    // threads (they leak until the descendant
                    // eventually exits and closes the fd -- a thread
                    // leak, not a memory-safety issue).
                    let stdout = stdout_rx.recv_timeout(READER_GRACE).ok();
                    let stderr = stderr_rx.recv_timeout(READER_GRACE).ok();
                    if stdout.is_none() || stderr.is_none() {
                        eprintln!(
                            "warning: `{program}` timed out and a descendant process \
                                 appears to still hold its output pipes open; captured \
                                 output may be incomplete"
                        );
                    }
                    return Err(CommandError::TimedOut {
                        program: program.to_string(),
                        seconds: timeout.as_secs(),
                    });
                }
                std::thread::sleep(Duration::from_millis(50));
            }
        }
    };

    // The direct child has exited on its own. Even so, a descendant
    // process can still hold the pipe fds open (e.g. a backgrounded
    // job spawned by a shell script), so bound the wait here too.
    let stdout_result = stdout_rx.recv_timeout(READER_GRACE);
    let stderr_result = stderr_rx.recv_timeout(READER_GRACE);
    // Incomplete output with a clean exit would read as an empty success to every classifier.
    let (Ok(stdout), Ok(stderr)) = (stdout_result, stderr_result) else {
        return Err(CommandError::Io {
            program: program.to_string(),
            message:
                "it exited but a descendant process still holds its output pipes open, so its output is incomplete"
                    .to_string(),
        });
    };

    Ok(CommandOutput {
        exit_code: status.code(),
        stdout,
        stderr,
    })
}

