        )
        .unwrap();
        let err = read_cargo_membership(dir.path()).err().unwrap();
        assert!(
            matches!(&err, LocateError::InvalidMembership { message, .. } if message.contains("workspace.exclude")),
            "{err:?}"
        );
    }

