/// The lockfile beside a Cargo workspace root manifest.
fn cargo_lockfile(root_manifest: &Path) -> PathBuf {
    root_manifest.with_file_name("Cargo.lock")
}

/// The ecosystems a plan touches, so only their lockfiles are refreshed and staged. Staging
/// the lockfile of an untouched ecosystem could sweep up unrelated user changes.
fn active_ecosystems(plan: &VersionPlan) -> HashSet<Ecosystem> {
    let of_manifest = |path: &Path| ManifestFormat::from_path(path).ok().map(|fmt| fmt.ecosystem());
    let mut active = HashSet::new();
    for bump in &plan.bumps {
        active.extend(bump.package.ecosystem());
        for write in &bump.writes {
            active.extend(match write {
                VersionWriteTarget::CargoWorkspacePackage { .. } => Some(Ecosystem::Cargo),
                VersionWriteTarget::Manifest(path) => of_manifest(path),
            });
        }
    }
    for rewrite in &plan.rewrites {
        active.extend(match &rewrite.key.target {
            DepWriteTarget::CargoWorkspaceDependency { .. } => Some(Ecosystem::Cargo),
            DepWriteTarget::Manifest(path) => of_manifest(path),
        });
    }
    active.extend(
        plan.platform_writes
            .iter()
            .filter_map(|write| of_manifest(&write.manifest)),
    );
    active.extend(
        plan.optional_dep_updates
            .iter()
            .filter_map(|update| of_manifest(&update.manifest)),
    );
    active
}

/// Runs `git <prefix> <paths...>` in `root`, mapping a non-zero exit to `GraphError::Command`.
fn run_git_on_paths<R: CommandRunner>(
    runner: &R,
    root: &Path,
    prefix: &[&str],
    paths: &[&PathBuf],
) -> Result<(), GraphError> {
    let rendered: Vec<String> = paths.iter().map(|p| p.display().to_string()).collect();
    let mut args: Vec<&str> = prefix.to_vec();
    args.extend(rendered.iter().map(String::as_str));
    let output = runner.run("git", &args, root)?;
    if !output.success() {
        return Err(GraphError::Command(CommandError::Failed {
            program: "git".to_string(),
            exit_code: output.exit_code,
            stderr: output.redacted_stderr(),
        }));
    }
    Ok(())
}

/// Regenerates the lockfile of each active ecosystem with the ecosystem's own tool. For Python,
/// exactly one lockfile is refreshed, in uv, poetry, pdm order.
fn refresh_lockfiles<R: CommandRunner>(
    runner: &R,
    root: &Path,
    cargo_workspaces: &BTreeSet<PathBuf>,
    lockfile_dirs: &LockfileDirs,
) -> Result<Vec<LockfileRefreshResult>, GraphError> {
    let mut refresh_results: Vec<LockfileRefreshResult> = Vec::new();

    for workspace in cargo_workspaces {
        let lockfile = cargo_lockfile(workspace);
        refresh_results.push(run_lockfile_refresh(
            runner,
            &root.join(workspace.parent().unwrap_or(Path::new(""))),
            &lockfile.to_string_lossy(),
            "cargo",
            &["update", "--workspace"],
        )?);
    }

    for dir in &lockfile_dirs.pypi {
        for (file, program, args) in PYPI_REFRESH {
            if path_exists(root, &dir.join(file))? {
                refresh_results.push(refresh_in(runner, root, dir, file, program, args)?);
                break;
            }
        }
    }

    for dir in &lockfile_dirs.npm {
        for (file, program, args) in NPM_REFRESH {
            if path_exists(root, &dir.join(file))? {
                refresh_results.push(refresh_in(runner, root, dir, file, program, args)?);
            }
        }
        for file in ["bun.lock", "bun.lockb"] {
            if path_exists(root, &dir.join(file))? {
                refresh_results.push(refresh_in(
                    runner,
                    root,
                    dir,
                    file,
                    "bun",
                    &["install", "--lockfile-only"],
                )?);
                break;
            }
        }
    }

    cache: &mut HashMap<PathBuf, Option<M>>,
    read: impl Fn(&Path) -> Result<Option<M>, LocateError>,
    admits: impl Fn(&M, &Path) -> bool,
) -> Result<bool, LocateError> {
    for ancestor in rel.ancestors().skip(1) {
        if ancestor.as_os_str().is_empty() || ancestor == Path::new(".") {
            break;
        }
        if !cache.contains_key(ancestor) {
            let membership = read(&root.join(ancestor))?;
            cache.insert(ancestor.to_path_buf(), membership);
        }
        if let Some(membership) = &cache[ancestor] {
            let within = rel.strip_prefix(ancestor).unwrap_or(rel);
            return Ok(admits(membership, within));
        }
    }
    Ok(true)
}

/// Whether a Cargo workspace nested below `root` admits the package at `rel`. The workspace at `root` is judged by
/// [`read_cargo_membership`]; this adds the verdict of a nearer workspace that governs the package, which judges it by its
/// own `members` and `exclude`. A package that is itself a workspace root, or that no nested workspace governs, passes.
pub(crate) fn nested_cargo_workspace_admits(
    root: &Path,
    rel: &Path,
    manifest_text: &str,
    nested: &mut NestedMemberships,
) -> Result<bool, LocateError> {
    let manifest = rel.join("Cargo.toml");
    let located = |error: ManifestError| match error {
        ManifestError::Parse { path, message, .. } => parse_error(&root.join(path), message),
        ManifestError::Read { path, message } => LocateError::ManifestReadError {
            path: root.join(path),
            message,
        },
        other => LocateError::ManifestReadError {
            path: root.join(&manifest),
            message: other.to_string(),
        },
    };
    let document = callisto_manifests::parse_manifest(&manifest, manifest_text).map_err(located)?;
    let Some(governing) = nested
        .reads
        .enclosing(&manifest, &document, callisto_manifests::read_manifest_text(root))
        .map_err(located)?
    else {
        return Ok(true);
    };
    let governing_dir = governing.parent().unwrap_or(Path::new(""));
    // A workspace named by `package.workspace` from outside the package's own ancestry has no path to judge by.
    let Ok(within) = rel.strip_prefix(governing_dir) else {
        return Ok(true);
    };
    if governing_dir.as_os_str().is_empty() || within.as_os_str().is_empty() {
        return Ok(true);
    }
    if !nested.cargo.contains_key(governing_dir) {
        let membership = read_cargo_membership(&root.join(governing_dir))?;
        nested.cargo.insert(governing_dir.to_path_buf(), membership);
    }
    Ok(nested.cargo[governing_dir].admits(within, false))
}

