/// Context passed to open() to supply workspace-wide inheritance facts.
pub struct OpenContext<'a> {
    pub workspace_root: &'a Path,
    /// The inheritance of the Cargo workspace rooted at `workspace_root`, loaded once and shared by its members.
    /// A manifest governed by another Cargo workspace loads that workspace's own.
    pub cargo_workspace: Option<Arc<WorkspaceInheritance>>,
    /// The other Cargo workspaces met while opening manifests.
    pub cargo_roots: CargoRoots,
    pub npm_workspace_kind: Option<WorkspaceKind>,
}

/// Cargo workspaces met while opening manifests, remembered so each is read once however many members inherit from it.
#[derive(Default)]
pub struct CargoRoots {
    reads: std::sync::Mutex<WorkspaceReads>,
    inheritance: std::sync::Mutex<std::collections::BTreeMap<std::path::PathBuf, Arc<WorkspaceInheritance>>>,
}

fn locked<T>(mutex: &std::sync::Mutex<T>) -> std::sync::MutexGuard<'_, T> {
    mutex.lock().unwrap_or_else(std::sync::PoisonError::into_inner)
}

impl<'a> OpenContext<'a> {
    /// Builds an [`OpenContext`] rooted at `root` by resolving Cargo
    /// workspace inheritance (when `root/Cargo.toml` exists) and detecting
    /// the npm workspace kind. This is the single reusable constructor for
    /// the "check Cargo.toml exists, load workspace inheritance, detect npm
    /// workspace kind" sequence that call sites previously reimplemented
    /// independently (audit pattern: duplication) -- see
    /// `callisto-graph`'s `walk`, `lib` (`Workspace::base_versions`),
    /// `apply`, and `commands::version` modules.
    ///
    /// # Errors
    ///
    /// A root `Cargo.toml` or `package.json` that exists but cannot be read or parsed. An inheriting member
    /// could not be opened without it, so a missing context is an error, never an empty one.
    pub fn for_workspace_root(root: &'a Path) -> Result<OpenContext<'a>, callisto_model::ManifestError> {
        let cargo_manifest = Path::new("Cargo.toml");
        let cargo_workspace = if callisto_model::strict_fs::exists(&root.join(cargo_manifest)).map_err(|e| {
            callisto_model::ManifestError::Read {
                path: cargo_manifest.to_path_buf(),
                message: e.to_string(),
            }
        })? {
            Some(Arc::new(
                WorkspaceCargoResolver::load_at(root, cargo_manifest)?.inheritance()?,
            ))
        } else {
            None
        };

        let npm_workspace_kind = detect_npm_workspace_kind(root)?;

        Ok(OpenContext {
            workspace_root: root,
            cargo_workspace,
            cargo_roots: CargoRoots::default(),
            npm_workspace_kind,
        })
    }

    /// The inheritance a Cargo manifest at `manifest` (workspace-relative, already parsed as `doc`) draws on: that of the
    /// Cargo workspace that governs it, which need not be the one at `workspace_root`.
    ///
    /// # Errors
    ///
    /// No Cargo workspace governs it, or the one that does cannot be read.
    pub(crate) fn cargo_inheritance(
        &self,
        manifest: &Path,
        doc: &toml_edit::DocumentMut,
    ) -> Result<Arc<WorkspaceInheritance>, ManifestError> {
        let found =
            locked(&self.cargo_roots.reads).enclosing(manifest, doc, cargo::read_manifest_text(self.workspace_root))?;
        let Some(root_manifest) = found else {
            return Err(ManifestError::Read {
                path: manifest.to_path_buf(),
                message: "declares .workspace = true but no Cargo workspace governs it: no Cargo.toml at or above its \
                          directory has a [workspace] table"
                    .to_string(),
            });
        };
        if let Some(shared) = self
            .cargo_workspace
            .as_ref()
            .filter(|shared| shared.root_manifest == root_manifest)
        {
            return Ok(Arc::clone(shared));
        }
        let mut loaded = locked(&self.cargo_roots.inheritance);
        if let Some(known) = loaded.get(&root_manifest) {
            return Ok(Arc::clone(known));
        }
        let inheritance =
            Arc::new(WorkspaceCargoResolver::load_at(self.workspace_root, &root_manifest)?.inheritance()?);
        loaded.insert(root_manifest, Arc::clone(&inheritance));
        Ok(inheritance)
    }
}

/// Test-observability counter: total number of times [`open`] has been
/// invoked. Production code never reads this; it exists so callers (in
/// particular, callers building a caching layer on top of `open()`) can
/// write regression tests asserting that a given manifest path is opened
/// (read + parsed from disk) at most once per logical operation, instead of
/// once per call site. See `callisto-graph`'s `manifest_cache` module.
static OPEN_CALL_COUNT: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);

/// Resets the internal manifest-open call counter to zero. Intended for use in test setup.
pub fn reset_open_call_count() {
    OPEN_CALL_COUNT.store(0, std::sync::atomic::Ordering::SeqCst);
}

/// Reads the current value of the internal manifest-open call counter.
pub fn open_call_count() -> usize {
    OPEN_CALL_COUNT.load(std::sync::atomic::Ordering::SeqCst)
}

/// Test-observability counter: total number of times a `Manifest`
/// implementor's `persist` has returned `Ok`. Production code never reads
/// this; it exists so callers can write regression tests asserting a given
/// manifest path is flushed to disk at most once per logical operation.
/// Distinct from `OPEN_CALL_COUNT` so open-count and persist-count
/// assertions in the same test are independent.
static PERSIST_CALL_COUNT: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);

/// Resets the internal manifest-persist call counter to zero. Intended for use in test setup.
pub fn reset_persist_call_count() {
    PERSIST_CALL_COUNT.store(0, std::sync::atomic::Ordering::SeqCst);
}

/// Reads the current value of the internal manifest-persist call counter.
pub fn persist_call_count() -> usize {
    PERSIST_CALL_COUNT.load(std::sync::atomic::Ordering::SeqCst)
}

/// Increments PERSIST_CALL_COUNT by one. Called by each Manifest
/// implementor's persist() immediately after its own atomic_write returns
/// Ok; PERSIST_CALL_COUNT itself is private to this module, so this is the
/// only way other modules in this crate may increment it.
