/// The membership of each workspace nested below the workspace root, keyed by its directory (`None` where the directory
/// declares no workspace), and what has been learned about Cargo workspace manifests on the way.
#[derive(Default)]
pub(crate) struct NestedMemberships {
    cargo: HashMap<PathBuf, Membership>,
    reads: callisto_manifests::WorkspaceReads,
    npm: HashMap<PathBuf, Option<NpmMembership>>,
    python: HashMap<PathBuf, Option<Membership>>,
}

/// Whether the workspaces nested below `root` admit the package of `ecosystem` at `rel`. The workspace at `root` is
/// judged by the `read_*_membership` of each ecosystem; this adds the verdict of a nearer one, which judges the package
/// by its own list. `manifest_text` is the package's own manifest.
pub(crate) fn nested_workspace_admits(
    root: &Path,
    rel: &Path,
    ecosystem: callisto_model::Ecosystem,
    manifest_text: &str,
    nested: &mut NestedMemberships,
) -> Result<bool, LocateError> {
    use callisto_model::Ecosystem;
    match ecosystem {
        Ecosystem::Cargo => nested_cargo_workspace_admits(root, rel, manifest_text, nested),
        Ecosystem::Npm => {
            let cache = &mut nested.npm;
            judged_by_nearest_declared_workspace(
                root,
                rel,
                cache,
                |dir| read_npm_membership(dir).map(|membership| membership.globs.is_some().then_some(membership)),
                |membership, within| membership.admits(within, false),
            )
        }
        Ecosystem::Pypi => {
            let cache = &mut nested.python;
            judged_by_nearest_declared_workspace(
                root,
                rel,
                cache,
                |dir| read_python_membership(dir).map(|membership| membership.declared.then_some(membership)),
                |membership, within| membership.admits(within, false),
            )
        }
        _ => Ok(true),
    }
}

/// The nearest directory above `rel`, below `root`, whose own manifest declares a workspace judges `rel` by its list,
/// with `rel` taken relative to it. With no such directory nothing nested has an opinion.
fn judged_by_nearest_declared_workspace<M>(
    root: &Path,
    rel: &Path,
    cache: &mut HashMap<PathBuf, Option<M>>,
    read: impl Fn(&Path) -> Result<Option<M>, LocateError>,
    admits: impl Fn(&M, &Path) -> bool,
) -> Result<bool, LocateError> {
    for ancestor in rel.ancestors().skip(1) {
        if ancestor.as_os_str().is_empty() || ancestor == Path::new(".") {
            break;
        }
        if !cache.contains_key(ancestor) {
            let membership = read(&root.join(ancestor))?;
            cache.insert(ancestor.to_path_buf(), membership);
        }
        if let Some(membership) = &cache[ancestor] {
            let within = rel.strip_prefix(ancestor).unwrap_or(rel);
            return Ok(admits(membership, within));
        }
    }
    Ok(true)
}

/// Whether a Cargo workspace nested below `root` admits the package at `rel`. The workspace at `root` is judged by

    fn projects(&self) -> Result<Vec<ProjectRoot>, LocateError> {
        Ok(self.projects_and_platform_candidates()?.0)
    }

    fn projects_and_platform_candidates(&self) -> Result<(Vec<ProjectRoot>, Vec<ProjectRoot>), LocateError> {
        let mut results = Vec::new();
        let mut platform_candidates = Vec::new();
        let cargo_membership = membership::read_cargo_membership(&self.root)?;
        let npm_membership = membership::read_npm_membership(&self.root)?;
        let python_membership = membership::read_python_membership(&self.root)?;
        let mut nested = membership::NestedMemberships::default();
        let walker = WalkBuilder::new(&self.root)
            .hidden(true)
            .git_ignore(true)
            // A workspace root below the Git toplevel has no `.git` of its own, but its `.gitignore` must still apply.
            .require_git(false)
            .parents(false)
            .max_depth(Some(32))
            // Links are followed only so a package beneath one can be named and rejected; the depth cap bounds a cycle.
            .follow_links(true)
            .filter_entry({
                let skip = self.skip.clone();
                move |entry| {
                    if let Some(name) = entry.file_name().to_str() {
                        if skip.contains(name) {
                            return false;
                        }
                    }
                    true
                }
            })
            .build();

        for entry_res in walker {
            let entry = entry_res.map_err(|e| LocateError::Walk {
                path: self.root.clone(),
                message: e.to_string(),
            })?;

            let path = entry.path();
            if !path.is_dir() {
                continue;
            }

            let rel = to_workspace_relative(path, &self.root)?;
            let is_root = rel == Path::new(".");
            let admits = |ecosystem: Ecosystem| match ecosystem {
                Ecosystem::Cargo => cargo_membership.admits(&rel, is_root),
                Ecosystem::Npm => npm_membership.admits(&rel, is_root),
                Ecosystem::Pypi => python_membership.admits(&rel, is_root),
                _ => false,
            };
            // Own-path check for a *failed* manifest: only a real, explicit members/workspaces
            // match counts -- the admit-all fallback (no restriction present, e.g. because this
            // very manifest is the one that failed to parse) must not count as membership.
            let admits_explicitly = |ecosystem: Ecosystem| match ecosystem {
                Ecosystem::Cargo => cargo_membership.admits_explicitly(&rel, is_root),
                Ecosystem::Npm => npm_membership.admits_explicitly(&rel, is_root),
                Ecosystem::Pypi => python_membership.admits_explicitly(&rel, is_root),
                _ => false,
            };

            // First pass: read and parse every canonical manifest present in this
            // directory, so a parse failure below can check whether a *sibling*
            // manifest here was admitted, not only its own ecosystem's membership.
            let mut parsed: Vec<(Ecosystem, String, callisto_manifests::ManifestIdentity)> = Vec::new();
            let mut failures: Vec<(PathBuf, ManifestFailure)> = Vec::new();
            for ecosystem in Ecosystem::CANONICAL {
                // Every `Ecosystem::CANONICAL` member has a canonical
                // manifest format by construction -- see its doc comment.
                let format = ecosystem
                    .canonical_manifest_format()
                    .expect("CANONICAL ecosystems always have a canonical manifest format");
                let manifest_path = path.join(format.file_name());
                let content = match callisto_model::strict_fs::read_optional(&manifest_path) {
                    Ok(Some(content)) => content,
                    Ok(None) => continue,
                    Err(e) => {
                        failures.push((manifest_path, ManifestFailure::Unreadable(e.to_string())));
                        continue;
                    }
                };
                match callisto_manifests::read_identity(format, &content, &manifest_path) {
                    Ok(identity) => parsed.push((ecosystem, content, identity)),
                    Err(e) => failures.push((manifest_path, ManifestFailure::Unparseable(e.to_string()))),
                }
            }

            // Explicit only, like `self_admitted` below -- a sibling that's merely admitted by
            // the fallback admit-all (no restriction present for that ecosystem) doesn't make
            // this directory a real, deliberate workspace member; only a genuine members/
            // workspaces match does.
            let any_sibling_admitted = parsed
                .iter()
                .any(|(ecosystem, _, identity)| identity.name.is_some() && admits_explicitly(*ecosystem));

            for (manifest_path, failure) in failures {
                // Determine which ecosystem this failed manifest belongs to from its
                // file name, to check its own membership independent of any sibling.
                let ecosystem = Ecosystem::CANONICAL.into_iter().find(|eco| {
                    eco.canonical_manifest_format()
                        .is_some_and(|f| Some(f.file_name()) == manifest_path.file_name().and_then(|n| n.to_str()))
                });
                let self_admitted = ecosystem.is_some_and(admits_explicitly);
                if self_admitted || any_sibling_admitted {
                    return Err(match failure {
                        ManifestFailure::Unreadable(message) => LocateError::ManifestReadError {
                            path: manifest_path,
                            message,
                        },
                        ManifestFailure::Unparseable(message) => LocateError::ManifestParseError {
                            path: manifest_path,
                            message,
                        },
                    });
                }
                eprintln!("{}", unparseable_manifest_warning(&manifest_path, &failure));
            }

            for (ecosystem, content, identity) in parsed {
                let Some(name) = identity.name else {
                    continue;
                };

                // A private, versionless package.json that holds an npm workspace (the standard root layout,
                // e.g. `@changesets/cli`, or one below the root) declares a name only to hold `workspaces`; it
                // is never itself a released package, so it never becomes a project.
                if ecosystem == Ecosystem::Npm
                    && identity.version.is_none()
                    && callisto_manifests::npm_declares_private(&content)
                    && (is_root || membership::declares_npm_workspace(path)?)
                {
                    continue;
                }

                let admitted = admits(ecosystem)
                    && (is_root
                        || membership::nested_workspace_admits(&self.root, &rel, ecosystem, &content, &mut nested)?);
                let id = PackageId::parse(&name).unwrap_or_else(|_| PackageId::Bare(name.clone()));
                let project = ProjectRoot {
                    id,
                    path: rel.clone(),
                    ecosystem,
                };
                if admitted {
                    reject_symlinked_package(&self.root, &rel)?;
                    results.push(project);
                } else if ecosystem == Ecosystem::Npm && callisto_manifests::npm_role_from_source(&content).is_some() {
                    reject_symlinked_package(&self.root, &rel)?;
                    platform_candidates.push(project);
                }
            }
        }

        results.sort_by(|a, b| (&a.path, a.ecosystem).cmp(&(&b.path, b.ecosystem)));
        platform_candidates.sort_by(|a, b| a.path.cmp(&b.path));
        Ok((results, platform_candidates))
    }
}

/// Git cannot stage a path beneath a symbolic link, so a package there could be edited on disk but never committed.

// Must run before the staging loop below, so refreshed lockfiles are on disk to be staged.
if opts.refresh_lockfiles {
    let refresh_results = refresh_lockfiles(runner, root, &cargo_workspaces, &lockfile_dirs)?;
    if !refresh_results.is_empty() {
        outcome.lockfile_refresh_results = Some(refresh_results);
    }
}

// Stage each lockfile of an active ecosystem that exists beside the workspace the plan wrote into.
let beside = |dirs: &BTreeSet<PathBuf>, names: &[&str]| -> Vec<PathBuf> {
    dirs.iter()
        .flat_map(|dir| names.iter().map(move |name| dir.join(name)))
        .collect()
};
let candidates = beside(&lockfile_dirs.npm, &NPM_LOCKFILES)
    .into_iter()
    .chain(beside(&lockfile_dirs.pypi, &PYPI_LOCKFILES));
let mut lockfile_paths: Vec<PathBuf> = Vec::new();
for p in candidates {
    if path_exists(root, &p)? && !modified_paths.contains(&p) {
        lockfile_paths.push(p.clone());
        modified_paths.push(p);
    }
}
for lockfile in cargo_workspaces.iter().map(|workspace| cargo_lockfile(workspace)) {
    if path_exists(root, &lockfile)? && !modified_paths.contains(&lockfile) {
        lockfile_paths.push(lockfile.clone());
        modified_paths.push(lockfile);
    }
}

// A lockfile that a .gitignore ignores (a library's `Cargo.lock`, say) is not meant to be committed: refreshed on disk,
// never staged. Anything else the plan stages was checked before the first write.
if !opts.transient {
    let ignored = preflight::ignored_paths(runner, root, &lockfile_paths)?;
    modified_paths.retain(|path| !ignored.contains(path));
}

if !opts.transient && (!modified_paths.is_empty() || !deferred_deletions.is_empty()) {
    // Stage all written release state before consuming its inputs. If a refresh or add fails,
    // the changesets/pre-state remain available; if removal staging fails, the manifest diff
    // still identifies the interrupted run.
    let mut existing = Vec::new();
    let mut deleted = Vec::new();
    for path in &modified_paths {
        if path_exists(root, path)? {
            existing.push(path);
        } else {
            deleted.push(path);
        }
    }

    if !existing.is_empty() {
        run_git_on_paths(runner, root, &["add", "--"], &existing)?;
    }

    if !deleted.is_empty() {
        run_git_on_paths(runner, root, &["rm", "--cached", "--ignore-unmatch", "--"], &deleted)?;
    }

    if !deferred_deletions.is_empty() {
        let deferred: Vec<&PathBuf> = deferred_deletions.iter().collect();
        run_git_on_paths(runner, root, &["rm", "--cached", "--ignore-unmatch", "--"], &deferred)?;

        // Keep the inputs on disk until their removal is staged so a failed index update can be retried.
        for path in &deferred_deletions {
            match fs::remove_file(root.join(path)) {
                Ok(()) => {}
                Err(e) if e.kind() == std::io::ErrorKind::NotFound => {}
                Err(e) => {
                    return Err(GraphError::ApplyIo {

    }
    // One quiet run answers the usual "none ignored"; only when something is does each path get asked, so no output
    // needs parsing (git quotes unusual names).
    if !any_ignored(runner, root, paths)? {
        return Ok(BTreeSet::new());
    }
    let mut ignored = BTreeSet::new();
