//! Pure argv construction for "publish a package to its registry", plus
//! subprocess-output classification for the same three ecosystems (Cargo,
//! npm, PyPI).
//!
//! This module owns exactly two questions per ecosystem: *what command do we
//! run* (given package/plan facts and already-detected environment facts --
//! never a [`callisto_model::CommandRunner`] call of its own) and *what did
//! the finished command's output mean*. Actually invoking the command, and
//! any retry/backoff policy around a failed attempt, is the caller's job --
//! see the durable release executor's single production publish path.
//!
//! A small amount of local filesystem reading happens here (the Cargo
//! on-disk version check, npm package-manager detection from lockfiles, the
//! PyPI interpreter's PATH lookup) -- that's "gathering the facts needed to
//! build the right argv", not executing a publish. It never shells out.

use std::ffi::OsStr;
use std::path::{Path, PathBuf};
use std::time::Duration;

use callisto_manifests::WorkspaceCargoResolver;
use callisto_model::{CommandOutput, Ecosystem, NpmAccess, PackageId, PublishOutcome, RegistryError, Version};

use crate::error::{GraphError, ReleasePreconditionRequirement};

/// Default fallback wait (seconds) when a registry does not supply a
/// `retry_after` value and the classifier cannot parse one from output.
const DEFAULT_RATE_LIMIT_WAIT_SECS: u64 = 60;

/// One subprocess invocation: program, args, and working directory. Building
/// this is the entire job of the `*_publish_argv` functions below --
/// executing it is the caller's.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Argv {
    pub program: String,
    pub args: Vec<String>,
    pub cwd: PathBuf,
}

// ---------------------------------------------------------------- cargo

/// Builds the exact `cargo publish` argv for one crate: `--manifest-path`
/// (so the caller can keep the workspace root as its own working directory)
/// plus `--locked`, so a stale `Cargo.lock` fails the publish immediately
/// instead of `cargo` silently re-resolving one at publish time.
/// `registry_key` is `Some` only for a non-default registry -- crates.io is
/// the implicit default and never needs `--registry`.
///
/// Before returning, verifies that the on-disk `Cargo.toml` version under
/// `package_dir` (resolving `version.workspace = true` against the
/// workspace root's `[workspace.package].version` when present) matches
/// `version` -- this is the one behavior `SubprocessRegistryClient` had that
/// the durable release executor's own `dispatch_registry` had silently
/// dropped: it catches the common mistake of running `release execute`
/// without first running `callisto version`, which would otherwise silently
/// publish the old on-disk version.
pub fn cargo_publish_argv(
    workspace_root: &Path,
    package_dir: &Path,
    package_name: &str,
    version: &Version,
    registry_key: Option<&str>,
) -> Result<Argv, GraphError> {
    verify_cargo_ondisk_version(workspace_root, package_dir, package_name, version)?;

    let manifest_path = workspace_root.join(package_dir).join("Cargo.toml");
    let mut args = vec![
        "publish".to_string(),
        "--manifest-path".to_string(),
        manifest_path.to_string_lossy().into_owned(),
        "--locked".to_string(),
    ];
    if let Some(reg) = registry_key {
        args.push("--registry".to_string());
        args.push(reg.to_string());
    }
    Ok(Argv {
        program: "cargo".to_string(),
        args,
        cwd: cargo_workspace_dir(workspace_root, package_dir)?,
    })
}

/// The directory of the Cargo workspace the package at `package_dir` belongs to. Cargo reads `.cargo/config.toml`
/// (registries, credentials) from where it runs, so a command about the package runs here, not at the workspace root.
pub(crate) fn cargo_workspace_dir(workspace_root: &Path, package_dir: &Path) -> Result<PathBuf, GraphError> {
    let root_manifest = callisto_manifests::cargo_workspace_of(
        &mut callisto_manifests::WorkspaceReads::default(),
        workspace_root,
        &package_dir.join("Cargo.toml"),
    )?;
    Ok(workspace_root.join(root_manifest.parent().unwrap_or(Path::new(""))))
}

fn verify_cargo_ondisk_version(
    workspace_root: &Path,
    package_dir: &Path,
    package_name: &str,
    planned: &Version,
) -> Result<(), GraphError> {
    let manifest_path = workspace_root.join(package_dir).join("Cargo.toml");
    let contents = std::fs::read_to_string(&manifest_path).map_err(|error| GraphError::ReleaseInputRead {
        path: manifest_path.clone(),
        message: error.to_string(),
    })?;
    // Parse only the [package].version field -- no need for full CST. A
    // permissive `toml::Value` intermediate rather than a direct `String`
    // deserialization, because `version.workspace = true` (Cargo's
    // workspace-version-inheritance syntax) parses `version` as a table, not
    // a string.
    let parsed = toml::from_str::<toml::Value>(&contents).map_err(|error| GraphError::ReleaseInputRead {
        path: manifest_path.clone(),
        message: error.to_string(),
    })?;
    let version_value =
        parsed
            .get("package")
            .and_then(|p| p.get("version"))
            .ok_or_else(|| GraphError::ReleaseInputRead {
                path: manifest_path.clone(),
                message: "missing [package].version".to_string(),
            })?;

    let on_disk = if let Some(s) = version_value.as_str() {
        s.to_string()
    } else if version_value.get("workspace").and_then(toml::Value::as_bool) == Some(true) {
        let member = package_dir.join("Cargo.toml");
        let document = callisto_manifests::parse_manifest(&member, &contents)?;
        let root_manifest = callisto_manifests::enclosing_workspace_manifest(workspace_root, &member, &document)?
            .ok_or_else(|| GraphError::ReleaseInputRead {
                path: manifest_path.clone(),
                message: "`version.workspace = true` but no Cargo workspace governs it".to_string(),
            })?;
        let root_manifest_path = workspace_root.join(&root_manifest);
        let resolver = WorkspaceCargoResolver::load_at(workspace_root, &root_manifest)?;
        let ws_version = resolver
            .workspace_version()?
            .ok_or_else(|| GraphError::ReleaseInputRead {
                path: root_manifest_path.clone(),
                message: "`version.workspace = true` but the workspace root has no [workspace.package].version"
                    .to_string(),
            })?;
        ws_version.render().to_string()
    } else {
        return Err(GraphError::ReleaseInputRead {
            path: manifest_path,
            message: "[package].version is neither a string nor a `{ workspace = true }` table".to_string(),
        });
    };

    let found = Version::parse(&on_disk, planned.grammar())?;
    if found != *planned {
        return Err(GraphError::OnDiskVersionDrift {
            package: PackageId::Prefixed {
                ecosystem: Ecosystem::Cargo,
                name: package_name.to_string(),
            },
            expected: planned.clone(),
            found,
        });
    }
    Ok(())
}

// ------------------------------------------------------------------ npm

/// The npm-compatible package manager a workspace uses, detected from
/// lockfile presence. Each one needs a materially different invocation to
/// publish a single named package out of a monorepo -- see
/// [`npm_publish_argv`].
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum NpmPackageManager {
    Pnpm,
    Yarn,
    Bun,
    Npm,
}

/// The files that mark a directory as an npm-family workspace root.
const NPM_WORKSPACE_MARKERS: [&str; 6] = [
    "pnpm-workspace.yaml",
    "pnpm-lock.yaml",
    "yarn.lock",
    "bun.lock",
    "bun.lockb",
    "package-lock.json",
];

/// The directory, relative to `workspace_root`, of the npm workspace that holds the package at `package_dir`: the nearest
/// one at or above it carrying a lockfile or a `pnpm-workspace.yaml`, else the workspace root.
///
/// # Errors
///
/// A directory on the way up cannot be inspected.
pub(crate) fn npm_workspace_dir(workspace_root: &Path, package_dir: &Path) -> Result<PathBuf, GraphError> {
    let mut dir = package_dir;
    loop {
        for marker in NPM_WORKSPACE_MARKERS {
            let marker = workspace_root.join(dir).join(marker);
            if callisto_model::strict_fs::exists(&marker).map_err(|error| GraphError::ReleaseInputRead {
                path: marker.clone(),
                message: error.to_string(),
            })? {
                return Ok(if dir == Path::new(".") {
                    PathBuf::new()
                } else {
                    dir.to_path_buf()
                });
            }
        }
        match dir.parent() {
            Some(parent) => dir = parent,
            None => return Ok(PathBuf::new()),
        }
    }
}

/// Detects the npm-compatible package manager of the workspace in `workspace_dir` from the files that mark it.
/// Detection priority: pnpm > yarn > bun > npm (default). A `pnpm-workspace.yaml` is pnpm even where the lockfile is not
/// committed, and a file that cannot be inspected is an error, not a reason to fall back to `npm`.
///
/// This is real, live-today correctness content: the durable release
/// executor's `dispatch_registry` used to hardcode plain `npm publish`
/// regardless of which package manager a workspace actually uses, so a pnpm
/// or yarn workspace published with the wrong tool.
///
/// # Errors
///
/// A marker file cannot be inspected.
pub fn detect_npm_package_manager(workspace_dir: &Path) -> Result<NpmPackageManager, GraphError> {
    let present = |name: &str| -> Result<bool, GraphError> {
        let path = workspace_dir.join(name);
        callisto_model::strict_fs::exists(&path).map_err(|error| GraphError::ReleaseInputRead {
            path,
            message: error.to_string(),
        })
    };
    Ok(if present("pnpm-lock.yaml")? || present("pnpm-workspace.yaml")? {
        NpmPackageManager::Pnpm
    } else if present("yarn.lock")? {
        NpmPackageManager::Yarn
    } else if present("bun.lockb")? || present("bun.lock")? {
        // bun.lockb is the legacy binary lockfile format; bun.lock (text) is
        // written by Bun >= 1.1.1. Both signal a bun-managed workspace.
        NpmPackageManager::Bun
    } else {
        NpmPackageManager::Npm
    })
}

/// Builds the npm-ecosystem publish argv for one package, given the
/// already-detected `package_manager` (see [`detect_npm_package_manager`]).
///
/// | Package manager | Program | Base args                                  |
/// |------------------|---------|--------------------------------------------|
/// | Pnpm             | `pnpm`  | `publish --filter=<name> --no-git-checks`  |
/// | Yarn             | `yarn`  | `workspace <name> npm publish`             |
/// | Bun              | `bun`   | `publish` (run from `package_dir`)         |
/// | Npm              | `npm`   | `publish --workspace=<name>`               |
///

        .unwrap_or_else(|| manifest.to_path_buf()))
}

/// Every manifest that could be the workspace root of the package at `manifest`: each `Cargo.toml` above its directory,
/// and the one its working-tree `package.workspace` names. Fetch these from a commit before asking
/// [`WorkspaceReads::enclosing`] about it there.
///
/// # Errors
///
/// The package's own manifest cannot be read or parsed.
pub fn workspace_manifest_candidates(workspace_root: &Path, manifest: &Path) -> Result<Vec<PathBuf>, ManifestError> {
    let dir = manifest.parent().unwrap_or(Path::new(""));
    let mut candidates: Vec<PathBuf> = dir
        .ancestors()
        .skip(1)
        .map(|ancestor| ancestor.join("Cargo.toml"))
        .collect();
    let named = read_manifest_text(workspace_root)(manifest)?
        .map(|text| parse_manifest(manifest, &text))
        .transpose()?
        .and_then(|doc| {
            doc.get("package")
                .and_then(|package| package.get("workspace"))
                .and_then(toml_edit::Item::as_str)
                .and_then(|named| workspace_relative(dir.join(named)).ok())
        });
    candidates.extend(named.map(|root| root.join("Cargo.toml")));
    candidates.sort();
    candidates.dedup();
    Ok(candidates)
}

/// Whether the manifest declares a workspace. Cargo treats any `workspace` table as one, however it is spelled: a
/// `[workspace]` header, an inline table, dotted keys, or one that exists only as `[workspace.package]`.
pub fn declares_workspace(doc: &toml_edit::DocumentMut) -> bool {
    doc.get("workspace").is_some_and(toml_edit::Item::is_table_like)
}

/// Parses the text of the `Cargo.toml` at `manifest`, which is used only to name it in the error.
pub fn parse_manifest(manifest: &Path, text: &str) -> Result<toml_edit::DocumentMut, ManifestError> {
    text.strip_prefix('\u{FEFF}')
        .unwrap_or(text)
        .parse::<toml_edit::DocumentMut>()
        .map_err(|error| ManifestError::Parse {
            path: manifest.to_path_buf(),
            format: ManifestFormat::CargoToml,
            message: error.to_string(),
        })
}

/// Extracts `[package].name` from an already-parsed `Cargo.toml` document.
/// Pure and I/O-free -- operates on a document the caller already has,
/// whether that's a fully-opened [`CargoToml`] (via [`Manifest::package_name`])
/// or a bare parse a caller made for some other purpose entirely (e.g.
/// [`crate::read_identity`], which needs only a package name and deliberately
/// does not go through the full [`CargoToml::open`] lifecycle).
pub fn cargo_package_name(doc: &toml_edit::DocumentMut) -> Option<&str> {
    doc.get("package").and_then(|p| p.get("name")).and_then(|n| n.as_str())
}

/// Rewrites a dependency entry's `version` to `new_str`, preserving decor
/// across the three shapes Cargo allows for a dependency value: a bare
/// version string, an inline table with a `version` key, or a full
/// `[dependencies.name]` table with a `version` key. `Err(())` for any
/// other shape -- callers map that to their own
/// `ManifestError::UnrecognizedDependencyValue` (which needs a `path` this
/// function has no access to). Shared by the member-manifest
/// ([`CargoToml::update_dependency_spec`]) and workspace-root
/// ([`WorkspaceCargoResolver::write_dependency`]) dependency-write paths,
/// which were previously two copies of this exact three-shape dance,
/// differing only in which path they report on error.
fn set_dependency_version(item: &mut toml_edit::Item, new_str: String) -> Result<(), ()> {
    if let Some(value) = item.as_value_mut() {
        if value.is_str() {
            let decor = value.decor().clone();
            let mut new_val = toml_edit::Value::from(new_str);
            *new_val.decor_mut() = decor;
            *value = new_val;
        } else if let Some(inline) = value.as_inline_table_mut() {
            if let Some(existing_ver) = inline.get_mut("version") {
                let decor = existing_ver.decor().clone();
                let mut new_val = toml_edit::Value::from(new_str);
                *new_val.decor_mut() = decor;
                *existing_ver = new_val;
            } else {
                inline.insert("version", toml_edit::Value::from(new_str));
            }
        } else {
            return Err(());
        }
    } else if let Some(tbl) = item.as_table_mut() {
        let decor = tbl.get("version").and_then(|i| i.as_value()).map(|v| v.decor().clone());
        tbl.insert("version", toml_edit::value(new_str));
        if let Some(decor) = decor {
            if let Some(new_item) = tbl.get_mut("version").and_then(|i| i.as_value_mut()) {
                *new_item.decor_mut() = decor;
            }
        }
    } else {
        return Err(());
    }
    Ok(())
}

