/// The root manifest of each Cargo workspace the plan writes into. Each has its own `Cargo.lock` beside it.
fn touched_cargo_workspaces(root: &Path, plan: &VersionPlan) -> Result<BTreeSet<PathBuf>, GraphError> {
    let mut workspaces = BTreeSet::new();
    for write in plan.bumps.iter().flat_map(|bump| &bump.writes) {
        if let VersionWriteTarget::CargoWorkspacePackage { root_manifest } = write {
            workspaces.insert(root_manifest.clone());
        }
    }
    for rewrite in &plan.rewrites {
        if let DepWriteTarget::CargoWorkspaceDependency { root_manifest } = &rewrite.key.target {
            workspaces.insert(root_manifest.clone());
        }
    }
    let members = written_manifests(plan);
    let mut reads = callisto_manifests::WorkspaceReads::default();
    for member in members {
        if ManifestFormat::from_path(member) == Ok(ManifestFormat::CargoToml) {
            workspaces.insert(callisto_manifests::cargo_workspace_of(&mut reads, root, member)?);
        }
    }
    if workspaces.is_empty() {
        // Nothing names a workspace: a Cargo package was bumped without a manifest write of its own.
        workspaces.insert(PathBuf::from("Cargo.toml"));
    }
    Ok(workspaces)
}

/// Every manifest, other than a Cargo workspace root, the plan writes to.
fn written_manifests(plan: &VersionPlan) -> Vec<&Path> {
    let mut manifests: Vec<&Path> = Vec::new();
    for write in plan.bumps.iter().flat_map(|bump| &bump.writes) {
        if let VersionWriteTarget::Manifest(path) = write {
            manifests.push(path);
        }
    }
    for rewrite in &plan.rewrites {
        if let DepWriteTarget::Manifest(path) = &rewrite.key.target {
            manifests.push(path);
        }
    }
    manifests.extend(plan.platform_writes.iter().map(|write| write.manifest.as_path()));
    manifests.extend(plan.optional_dep_updates.iter().map(|update| update.manifest.as_path()));
    manifests
}

/// The lockfile beside a Cargo workspace root manifest.
fn cargo_lockfile(root_manifest: &Path) -> PathBuf {
    root_manifest.with_file_name("Cargo.lock")
}

/// The ecosystems a plan touches, so only their lockfiles are refreshed and staged. Staging
/// the lockfile of an untouched ecosystem could sweep up unrelated user changes.
fn active_ecosystems(plan: &VersionPlan) -> HashSet<Ecosystem> {
    let of_manifest = |path: &Path| ManifestFormat::from_path(path).ok().map(|fmt| fmt.ecosystem());
    let mut active = HashSet::new();
    for bump in &plan.bumps {
        active.extend(bump.package.ecosystem());
        for write in &bump.writes {
            active.extend(match write {
                VersionWriteTarget::CargoWorkspacePackage { .. } => Some(Ecosystem::Cargo),
                VersionWriteTarget::Manifest(path) => of_manifest(path),
            });
        }
    }
    for rewrite in &plan.rewrites {
        active.extend(match &rewrite.key.target {
            DepWriteTarget::CargoWorkspaceDependency { .. } => Some(Ecosystem::Cargo),
            DepWriteTarget::Manifest(path) => of_manifest(path),
        });
    }
    active.extend(
        plan.platform_writes
            .iter()
            .filter_map(|write| of_manifest(&write.manifest)),
    );
    active.extend(
        plan.optional_dep_updates
            .iter()
            .filter_map(|update| of_manifest(&update.manifest)),
    );
    active
}

/// Runs `git <prefix> <paths...>` in `root`, mapping a non-zero exit to `GraphError::Command`.
fn run_git_on_paths<R: CommandRunner>(
    runner: &R,
    root: &Path,
    prefix: &[&str],
    paths: &[&PathBuf],
) -> Result<(), GraphError> {
    let rendered: Vec<String> = paths.iter().map(|p| p.display().to_string()).collect();
    let mut args: Vec<&str> = prefix.to_vec();
    args.extend(rendered.iter().map(String::as_str));
    let output = runner.run("git", &args, root)?;
    if !output.success() {
        return Err(GraphError::Command(CommandError::Failed {
            program: "git".to_string(),
            exit_code: output.exit_code,
            stderr: output.redacted_stderr(),
        }));
    }
    Ok(())
}

/// Regenerates the lockfile of each active ecosystem with the ecosystem's own tool. For Python,
/// exactly one lockfile is refreshed, in uv, poetry, pdm order.
fn refresh_lockfiles<R: CommandRunner>(
    runner: &R,
    root: &Path,
    cargo_workspaces: &BTreeSet<PathBuf>,
    lockfile_dirs: &LockfileDirs,
) -> Result<Vec<LockfileRefreshResult>, GraphError> {
    let mut refresh_results: Vec<LockfileRefreshResult> = Vec::new();

    for workspace in cargo_workspaces {
        let lockfile = cargo_lockfile(workspace);
        refresh_results.push(run_lockfile_refresh(
            runner,
            &root.join(workspace.parent().unwrap_or(Path::new(""))),
            &lockfile.to_string_lossy(),
            "cargo",
            &["update", "--workspace"],
        )?);
    }

    for dir in &lockfile_dirs.pypi {
        for (file, program, args) in PYPI_REFRESH {
            if path_exists(root, &dir.join(file))? {
                refresh_results.push(refresh_in(runner, root, dir, file, program, args)?);
                break;
            }
        }
    }

    for dir in &lockfile_dirs.npm {
        for (file, program, args) in NPM_REFRESH {
            if path_exists(root, &dir.join(file))? {
                refresh_results.push(refresh_in(runner, root, dir, file, program, args)?);
            }
        }
        for file in ["bun.lock", "bun.lockb"] {
            if path_exists(root, &dir.join(file))? {
                refresh_results.push(refresh_in(
                    runner,
                    root,
                    dir,
                    file,
                    "bun",
                    &["install", "--lockfile-only"],
                )?);
                break;
            }
        }
    }

    Ok(refresh_results)
}

type Refresh = (&'static str, &'static str, &'static [&'static str]);

/// For Python exactly one lockfile is refreshed per directory, in this order.
const PYPI_REFRESH: [Refresh; 3] = [
    ("uv.lock", "uv", &["lock"]),
    ("poetry.lock", "poetry", &["lock", "--no-update"]),
    ("pdm.lock", "pdm", &["lock", "--update-reuse"]),
];

/// Each npm-family lockfile present is refreshed independently (bun's two spellings are handled apart).
const NPM_REFRESH: [Refresh; 3] = [
    (
        "package-lock.json",
        "npm",
        &["install", "--package-lock-only", "--ignore-scripts"],
    ),
    ("pnpm-lock.yaml", "pnpm", &["install", "--lockfile-only"]),
    ("yarn.lock", "yarn", &["install", "--mode", "update-lockfile"]),
];

const NPM_LOCKFILES: [&str; 5] = [
    "package-lock.json",
    "pnpm-lock.yaml",
    "yarn.lock",
    "bun.lock",
    "bun.lockb",
];
const PYPI_LOCKFILES: [&str; 4] = ["uv.lock", "poetry.lock", "pdm.lock", "Pipfile.lock"];

/// Runs the refresh of `dir/file` in `dir`, reporting the lockfile by its path from the workspace root.
fn refresh_in<R: CommandRunner>(
    runner: &R,
    root: &Path,
    dir: &Path,
    file: &str,
    program: &str,
    args: &[&str],
) -> Result<LockfileRefreshResult, GraphError> {
    run_lockfile_refresh(
        runner,
        &root.join(dir),
        &dir.join(file).to_string_lossy(),
        program,
        args,
    )
}

impl WorkspaceReads {
    /// The workspace-relative `Cargo.toml` of the Cargo workspace that governs the package at `manifest`, found the way
    /// Cargo finds it: the directory named by `package.workspace`, else the nearest manifest at or above the package's
    /// directory that has a `workspace` table. The search stops at the workspace root. `doc` is the package's own
    /// manifest and `manifest_at` supplies any other workspace-relative manifest's text, or `None` when there is none,
    /// so a past commit can answer as well as the working tree.
    ///
    /// # Errors
    ///
    /// A manifest on the way up that cannot be read or parsed (skipping it could settle on a different root), or a
    /// `package.workspace` that leaves the workspace root or names a manifest with no `workspace` table.
    pub fn enclosing<E: From<ManifestError>>(
        &mut self,
        manifest: &Path,
        doc: &toml_edit::DocumentMut,
        mut manifest_at: impl FnMut(&Path) -> Result<Option<String>, E>,
    ) -> Result<Option<PathBuf>, E> {
        let dir = manifest.parent().unwrap_or(Path::new(""));
        let read_error = |path: &Path, message: String| ManifestError::Read {
            path: path.to_path_buf(),
            message,
        };

        if let Some(named) = doc
            .get("package")
            .and_then(|package| package.get("workspace"))
            .and_then(toml_edit::Item::as_str)
        {
            let root_manifest = workspace_relative(dir.join(named))
                .map_err(|error| {
                    read_error(
                        manifest,
                        format!("`package.workspace = \"{named}\"` is unusable: {error}"),
                    )
                })?
                .join("Cargo.toml");
            return if self.declares(&root_manifest, &mut manifest_at)? {
                Ok(Some(root_manifest))
            } else {
                Err(read_error(
                    manifest,
                    format!(
                        "`package.workspace = \"{named}\"` names `{}`, which declares no `[workspace]`",
                        root_manifest.display()
                    ),
                )
                .into())
            };
        }

        for candidate in dir.ancestors() {
            let candidate_manifest = candidate.join("Cargo.toml");
            let declares_workspace = if candidate == dir {
                declares_workspace(doc)
            } else {
                self.declares(&candidate_manifest, &mut manifest_at)?
            };
            if declares_workspace {
                return Ok(Some(candidate_manifest));
            }
        }
        Ok(None)
    }

    /// The `[workspace.package]` version of the workspace manifest `root_manifest`, or `None` when it declares none.
    ///
    /// # Errors
    ///
    /// `root_manifest` is missing, cannot be parsed, or declares an invalid version; or `manifest_at` fails.
    pub fn version<E: From<ManifestError>>(
        &mut self,
        root_manifest: &Path,
        mut manifest_at: impl FnMut(&Path) -> Result<Option<String>, E>,
    ) -> Result<Option<Version>, E> {
        if let Some(known) = self.versions.get(root_manifest) {
            return Ok(known.clone());
        }
        let text = manifest_at(root_manifest)?.ok_or_else(|| ManifestError::Read {
            path: root_manifest.to_path_buf(),
            message: "No such file or directory".to_string(),
        })?;
        let version = workspace_version_from_source(&text, root_manifest)?;
        self.versions.insert(root_manifest.to_path_buf(), version.clone());
        Ok(version)
    }

    fn declares<E: From<ManifestError>>(
        &mut self,
        manifest: &Path,
        manifest_at: &mut impl FnMut(&Path) -> Result<Option<String>, E>,
    ) -> Result<bool, E> {
        if let Some(known) = self.declares.get(manifest) {
            return Ok(*known);
        }
        let declared = match manifest_at(manifest)? {
            Some(text) => declares_workspace(&parse_manifest(manifest, &text)?),
            None => false,
        };
        self.declares.insert(manifest.to_path_buf(), declared);
        Ok(declared)
    }
}

/// Reads workspace-relative manifest text from the working tree under `workspace_root`; `None` when there is none.
pub fn read_manifest_text(workspace_root: &Path) -> impl FnMut(&Path) -> Result<Option<String>, ManifestError> + '_ {
    move |manifest| {
        callisto_model::strict_fs::read_optional(&workspace_root.join(manifest)).map_err(|error| ManifestError::Read {
            path: manifest.to_path_buf(),
            message: error.to_string(),
        })
    }
}

/// The workspace-relative `Cargo.toml` of the Cargo workspace that governs the package at `manifest`, read from the
/// working tree; see [`WorkspaceReads::enclosing`]. `doc` is the package's own manifest.
pub fn enclosing_workspace_manifest(
    workspace_root: &Path,
    manifest: &Path,
    doc: &toml_edit::DocumentMut,
) -> Result<Option<PathBuf>, ManifestError> {
    WorkspaceReads::default().enclosing(manifest, doc, read_manifest_text(workspace_root))
}

/// The workspace-relative `Cargo.toml` of the Cargo workspace the package at `manifest` belongs to, read from the working
/// tree. A package that no workspace governs is a workspace of its own, which is where its `Cargo.lock` is written.
///
/// # Errors
///
/// A manifest on the way up that cannot be read or parsed, or an unusable `package.workspace`.
pub fn cargo_workspace_of(
    reads: &mut WorkspaceReads,
    workspace_root: &Path,
    manifest: &Path,
) -> Result<PathBuf, ManifestError> {
    let manifest = &workspace_relative(manifest).map_err(|error| ManifestError::Read {
        path: manifest.to_path_buf(),
        message: error.to_string(),
    })?;
    let text = read_manifest_text(workspace_root)(manifest)?.ok_or_else(|| ManifestError::Read {
        path: manifest.to_path_buf(),
        message: "No such file or directory".to_string(),
    })?;
    let doc = parse_manifest(manifest, &text)?;
    Ok(reads
        .enclosing(manifest, &doc, read_manifest_text(workspace_root))?
        .unwrap_or_else(|| manifest.to_path_buf()))
}

/// Every manifest that could be the workspace root of the package at `manifest`: each `Cargo.toml` above its directory,
/// and the one its working-tree `package.workspace` names. Fetch these from a commit before asking
/// [`WorkspaceReads::enclosing`] about it there.
///
/// # Errors
///
/// The package's own manifest cannot be read or parsed.
pub fn workspace_manifest_candidates(workspace_root: &Path, manifest: &Path) -> Result<Vec<PathBuf>, ManifestError> {
    let dir = manifest.parent().unwrap_or(Path::new(""));
    let mut candidates: Vec<PathBuf> = dir
        .ancestors()
        .skip(1)
        .map(|ancestor| ancestor.join("Cargo.toml"))
        .collect();
    let named = read_manifest_text(workspace_root)(manifest)?
        .map(|text| parse_manifest(manifest, &text))
        .transpose()?
        .and_then(|doc| {
            doc.get("package")
                .and_then(|package| package.get("workspace"))
                .and_then(toml_edit::Item::as_str)
                .and_then(|named| workspace_relative(dir.join(named)).ok())
        });
    candidates.extend(named.map(|root| root.join("Cargo.toml")));
    candidates.sort();
    candidates.dedup();
    Ok(candidates)
}

/// Whether the manifest declares a workspace. Cargo treats any `workspace` table as one, however it is spelled: a
/// `[workspace]` header, an inline table, dotted keys, or one that exists only as `[workspace.package]`.
pub fn declares_workspace(doc: &toml_edit::DocumentMut) -> bool {
    doc.get("workspace").is_some_and(toml_edit::Item::is_table_like)
}

/// Parses the text of the `Cargo.toml` at `manifest`, which is used only to name it in the error.
pub fn parse_manifest(manifest: &Path, text: &str) -> Result<toml_edit::DocumentMut, ManifestError> {
    text.strip_prefix('\u{FEFF}')
        .unwrap_or(text)
        .parse::<toml_edit::DocumentMut>()
        .map_err(|error| ManifestError::Parse {
            path: manifest.to_path_buf(),
            format: ManifestFormat::CargoToml,
            message: error.to_string(),
        })
}

/// Extracts `[package].name` from an already-parsed `Cargo.toml` document.

/// - Manifest parse/write failures (malformed TOML/JSON, unsupported format).
/// - Git subprocess failures (`git add`/`git rm --cached` non-zero exit).
/// - I/O errors writing changelog sections or `pre.json`.
pub fn apply_version_plan<R: CommandRunner>(
    root: &Path,
    plan: &VersionPlan,
    runner: &R,
    opts: &ApplyOptions,
    permit: &ApplyPermit,
) -> Result<ApplyOutcome, GraphError> {
    let mut outcome = ApplyOutcome::default();
    let mut modified_paths = Vec::new();
    let mut deferred_deletions = Vec::new();

    let ctx = OpenContext::for_workspace_root(root)?;
    preflight::check(root, plan, opts, permit, runner)?;
    let active_ecosystems = active_ecosystems(plan);
    // Resolved before the first write, so a workspace that cannot be found stops the run with nothing changed.
    let cargo_workspaces = if active_ecosystems.contains(&Ecosystem::Cargo) {
        touched_cargo_workspaces(root, plan)?
    } else {
        BTreeSet::new()
    };
    let lockfile_dirs = lockfile_dirs(root, plan, &active_ecosystems)?;
    let classification = classify_manifest_writes(plan);

    for step in write_steps(plan, &classification) {
        modified_paths.push(apply_write_step(&step, plan, root, &ctx, permit)?);
    }

    if !opts.transient {
        for cl in &plan.changelog_writes {
            let rendered = crate::changelog::render_section(&cl.input)?;
            crate::changelog::prepend(
                root,
                &cl.changelog_path,
                &cl.input.package.display_name(),
                &rendered,
                permit,
            )?;
            modified_paths.push(cl.changelog_path.clone());
        }

        for cs_path in &plan.consumed_changesets {
            deferred_deletions.push(cs_path.clone());
        }

        if let Some(ref pre_state) = plan.pre_state_update {
            // Written from `plan.pre_json_path`, not derived from `consumed_changesets` (always empty in pre mode).
            let rel_pre_path = plan.pre_json_path.clone();
            let pre_path = root.join(&rel_pre_path);
            let text = match &plan.pre_json_original_text {
                Some(existing) => callisto_model::format::write_pre_json_preserving(pre_state, existing),
                None => callisto_model::format::write_pre_json(pre_state),
            };
            callisto_manifests::atomic::atomic_write(&pre_path, &text, permit).map_err(|e| GraphError::ApplyIo {
                path: rel_pre_path.clone(),
                message: e.to_string(),
            })?;
            modified_paths.push(rel_pre_path);
        } else if let Some(rel_pre_path) = &plan.delete_pre_json {
            deferred_deletions.push(rel_pre_path.clone());
        }
    }

    // Must run before the staging loop below, so refreshed lockfiles are on disk to be staged.
    if opts.refresh_lockfiles {
        let refresh_results = refresh_lockfiles(runner, root, &cargo_workspaces, &lockfile_dirs)?;
        if !refresh_results.is_empty() {
            outcome.lockfile_refresh_results = Some(refresh_results);
        }
    }

    // Stage each lockfile of an active ecosystem that exists beside the workspace the plan wrote into.
    let beside = |dirs: &BTreeSet<PathBuf>, names: &[&str]| -> Vec<PathBuf> {
        dirs.iter()
            .flat_map(|dir| names.iter().map(move |name| dir.join(name)))
            .collect()
    };
    let candidates = beside(&lockfile_dirs.npm, &NPM_LOCKFILES)
        .into_iter()
        .chain(beside(&lockfile_dirs.pypi, &PYPI_LOCKFILES));
    let mut lockfile_paths: Vec<PathBuf> = Vec::new();
    for p in candidates {
