/// Default fallback wait (seconds) when a registry does not supply a
/// `retry_after` value and the classifier cannot parse one from output.
const DEFAULT_RATE_LIMIT_WAIT_SECS: u64 = 60;

/// One subprocess invocation: program, args, and working directory. Building
/// this is the entire job of the `*_publish_argv` functions below --
/// executing it is the caller's.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Argv {
    pub program: String,
    pub args: Vec<String>,
    pub cwd: PathBuf,
}

// ---------------------------------------------------------------- cargo

/// Builds the exact `cargo publish` argv for one crate: `--manifest-path`
/// (so the caller can keep the workspace root as its own working directory)
/// plus `--locked`, so a stale `Cargo.lock` fails the publish immediately
/// instead of `cargo` silently re-resolving one at publish time.
/// `registry_key` is `Some` only for a non-default registry -- crates.io is
/// the implicit default and never needs `--registry`.
///
/// Before returning, verifies that the on-disk `Cargo.toml` version under
/// `package_dir` (resolving `version.workspace = true` against the
/// workspace root's `[workspace.package].version` when present) matches
/// `version` -- this is the one behavior `SubprocessRegistryClient` had that
/// the durable release executor's own `dispatch_registry` had silently
/// dropped: it catches the common mistake of running `release execute`
/// without first running `callisto version`, which would otherwise silently
/// publish the old on-disk version.
pub fn cargo_publish_argv(
    workspace_root: &Path,
    package_dir: &Path,
    package_name: &str,
    version: &Version,
    registry_key: Option<&str>,
) -> Result<Argv, GraphError> {
    verify_cargo_ondisk_version(workspace_root, package_dir, package_name, version)?;

    let manifest_path = workspace_root.join(package_dir).join("Cargo.toml");
    let mut args = vec![
        "publish".to_string(),
        "--manifest-path".to_string(),
        manifest_path.to_string_lossy().into_owned(),
        "--locked".to_string(),
    ];
    if let Some(reg) = registry_key {
        args.push("--registry".to_string());
        args.push(reg.to_string());
    }
    Ok(Argv {
        program: "cargo".to_string(),
        args,
        cwd: cargo_workspace_dir(workspace_root, package_dir)?,
    })
}

/// The directory of the Cargo workspace the package at `package_dir` belongs to. Cargo reads `.cargo/config.toml`
/// (registries, credentials) from where it runs, so a command about the package runs here, not at the workspace root.
pub(crate) fn cargo_workspace_dir(workspace_root: &Path, package_dir: &Path) -> Result<PathBuf, GraphError> {
    let root_manifest = callisto_manifests::cargo_workspace_of(
        &mut callisto_manifests::WorkspaceReads::default(),
        workspace_root,
        &package_dir.join("Cargo.toml"),
    )?;
    Ok(workspace_root.join(root_manifest.parent().unwrap_or(Path::new(""))))
}

fn verify_cargo_ondisk_version(
    workspace_root: &Path,
    package_dir: &Path,
    package_name: &str,
    planned: &Version,
) -> Result<(), GraphError> {

/// A path is admitted only when it matches at least one `positive` pattern
/// and matches none of the `negative` (`!`-stripped) patterns -- mirroring
/// how npm/pnpm/Yarn actually resolve workspace globs (later patterns can
/// negate earlier ones; a leading `!` excludes). A positive-only pattern
/// list behaves exactly as a plain [`GlobSet`] would. An all-negative list
/// has an empty positive set, so `is_match` is always `false` -- there is no
/// positive baseline for the negation to carve an exclusion out of.
pub(crate) struct NegatableGlobSet {
    positive: GlobSet,
    negative: GlobSet,
}

impl NegatableGlobSet {
    pub(crate) fn is_match(&self, path: &Path) -> bool {
        self.positive.is_match(path) && !self.negative.is_match(path)
    }

    pub(crate) fn empty() -> Self {
        NegatableGlobSet {
            positive: GlobSet::empty(),
            negative: GlobSet::empty(),
        }
    }
}

/// `./packages/*` and `packages/*/` name the same directories as `packages/*`, but compiled as written they would
/// match no relative path and silently admit nothing.
fn normalize_pattern(pattern: &str) -> &str {
    let mut rest = pattern;
    while let Some(stripped) = rest.strip_prefix("./") {
        rest = stripped;
    }
    if rest.is_empty() && !pattern.is_empty() {
        return ".";
    }
    match rest.trim_end_matches('/') {
        "" => rest,
        trimmed => trimmed,
    }
}

/// Builds a [`NegatableGlobSet`] from a list of glob strings, matched with
/// `literal_separator(true)` semantics (`*` does not cross `/`; `**` does)
/// against forward-slash-normalized, workspace-relative paths. An entry
/// with a leading `!` is treated as a negative (exclusion) pattern -- see
/// [`NegatableGlobSet`].
///
/// An entry that fails to compile is an error: skipping it would leave an exclusion or a
/// member unapplied and change which packages the workspace admits.
pub(crate) fn build_globset(entries: &[String]) -> Result<NegatableGlobSet, globset::Error> {
    let mut positive = GlobSetBuilder::new();
    let mut negative = GlobSetBuilder::new();
    for entry in entries {
        let (builder, pattern) = match entry.strip_prefix('!') {
            Some(rest) => (&mut negative, rest),
            None => (&mut positive, entry.as_str()),
        };
        builder.add(
            GlobBuilder::new(normalize_pattern(pattern))
                .literal_separator(true)
                .build()?,
        );
    }
    Ok(NegatableGlobSet {
        positive: positive.build()?,
        negative: negative.build()?,
    })
}

