fn resolve_batch_versions(
    blobs: Vec<BatchBlob>,
    paths: &[&str],
    queries: &[(String, Ecosystem)],
) -> Result<Vec<callisto_manifests::EffectiveManifestVersion>, GraphError> {
    let sources: std::collections::BTreeMap<_, _> = paths.iter().copied().zip(blobs).collect();
    let mut reads = callisto_manifests::WorkspaceReads::default();
    let at_commit = |other: &std::path::Path| -> Result<Option<String>, callisto_model::ManifestError> {
        let unavailable = |message: String| callisto_model::ManifestError::Read {
            path: other.to_path_buf(),
            message,
        };
        let key = normalized_git_path(other).map_err(|error| unavailable(error.to_string()))?;
        match sources.get(key.as_str()) {
            Some(BatchBlob::Blob(text)) => Ok(Some(text.clone())),
            Some(BatchBlob::Missing) => Ok(None),
            None => Err(unavailable(
                "needed to resolve an inherited version but was not fetched from the commit".to_string(),
            )),
        }
    };
    queries
        .iter()
        .map(|(path, ecosystem)| {
            let Some(BatchBlob::Blob(source)) = sources.get(path.as_str()) else {
                return Err(command_malformed_output(
                    "git",
                    &["cat-file", "--batch"],
                    format!("canonical manifest `{path}` was reported missing at the queried commit"),
                ));
            };
            let format = ecosystem
                .canonical_manifest_format()
                .ok_or_else(|| GraphError::ReleaseInvariant {
                    detail: format!("canonical manifest `{path}` has no canonical manifest format"),
                })?;
            callisto_manifests::read_effective_version(
                format,
                source,
                std::path::Path::new(path),
                &mut reads,
                at_commit,
            )
            .map_err(historical_manifest_error)?
            .ok_or_else(|| {
                command_malformed_output(
                    "git",
                    &["cat-file", "--batch"],
                    format!("manifest `{path}` has no effective declared version"),
                )
            })
        })
        .collect()
}

fn reason_from_bump(
    reason: Option<&BumpReason>,
    package_ids: &std::collections::BTreeMap<callisto_model::PackageId, Vec<ReleasePackageId>>,
) -> Result<ReleaseInclusionReason, GraphError> {
    match reason {
        Some(BumpReason::Changeset { .. }) | None => Ok(ReleaseInclusionReason::Changeset),
        Some(BumpReason::Inference { .. }) => Ok(ReleaseInclusionReason::Inference),
        Some(BumpReason::LinkedGroupUnion { group }) => Ok(ReleaseInclusionReason::LinkedGroup {
            group_id: group.to_string(),
        }),

